window.QB_POOLS=window.QB_POOLS||{};window.QB_POOLS["q203971c199"]={"type":"实验设计","questions":[{"qid":"sy-c-20260329-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"A ①③②⑤④ B ①④②⑤③ C. ③①⑤④② D. ③②⑤④①","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20260329-096-题目-p19-416-461.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2026-03-29-m96-材料-p19-130-416.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20260329-096-解析-p31-232-420.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"实验步骤中，①到⑤的顺序是错误的，正确的顺序是( ) 。\n\nA ①③②⑤④ B ①④②⑤③ C. ③①⑤④② D. ③②⑤④①","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"material":"材料五实验材料:电子天平、时娟、士甘蜗钳、酒精喷灯、玻璃棒、银子、烧杯、;高营、候带、稀盐酸、盼西k指示剂、 蒸情水实验步骤:\n\n①将士甘闲放在电子天平上称量，记录空时士写的质量\n\n②冷却后，用电子天平称量柑周和氧化锐的总质量\n\n③用电子天平称量一小段候带，记录质量\n\n④用酒精喷灯加热候带至完全燃烧\n\n⑤用链子将候带放入卅呐，再次称量，记录总质量\n\n⑥分析判断氧化锐的化学式\n\n⑦取少量氧化娱粉末，加入蒸馆水， 搅拌后观察是否溶解\n\n⑧滴力口盼酥指示剂，观察颜色变化(盼酥指示剂在酸性、中性环境中元色，在弱域性环境中主浅红色)\n\n⑨向上述溶液中滴力口稀盐酸，搅拌后观察现象","explanation":"96.答案C。\n\n观察选项，对比步骤①和步骤③，步骤①为称量空的质量，步骤③为称量镁带的质量，二者均属于实验前的准备工作，在整个实验步骤中应当前置，且均可作为第一步，无法排除选项。\n\n继续观察选项，B、D项中有步骤④和步骤②，步骤④为加热镁带，步骤②为“冷却后”的称量，属于实验的实质性开展，二者均应当在准备工作之后，即步骤④和步骤②都应在步骤①和步骤③之后，排除B、\n\nD项。\n\n根据步骤先加热、再冷却的顺序，步骤④应当在步骤②之前，排除A项。\n\n验证C项，③（测镁带）→①（测空埚）→③（测+镁带）→④（加热燃烧）→②（冷却后测总质量），符合逻辑。"},"from":{"file":"07-事业编职测/C类/2026/2026-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[31]},"idx":95,"pid":"p890e27c70b","sourceYears":[2026]},{"qid":"sy-c-20260329-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"Ä. 仅① B . 仅② C. 仅①③ D. 仅②③","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20260329-097-题目-p19-457-523.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2026-03-29-m96-材料-p19-130-416.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20260329-097-解析-p31-416-646.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"如要根据实验结果判断氧化镜的化学式，在①氧气的化学式、②氧原子的摩尔质量、③楼的摩尔质量三者之中，必须补充的条件是( ) 。\n\nÄ. 仅① B . 仅② C. 仅①③ D. 仅②③","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"material":"材料五实验材料:电子天平、时娟、士甘蜗钳、酒精喷灯、玻璃棒、银子、烧杯、;高营、候带、稀盐酸、盼西k指示剂、 蒸情水实验步骤:\n\n①将士甘闲放在电子天平上称量，记录空时士写的质量\n\n②冷却后，用电子天平称量柑周和氧化锐的总质量\n\n③用电子天平称量一小段候带，记录质量\n\n④用酒精喷灯加热候带至完全燃烧\n\n⑤用链子将候带放入卅呐，再次称量，记录总质量\n\n⑥分析判断氧化锐的化学式\n\n⑦取少量氧化娱粉末，加入蒸馆水， 搅拌后观察是否溶解\n\n⑧滴力口盼酥指示剂，观察颜色变化(盼酥指示剂在酸性、中性环境中元色，在弱域性环境中主浅红色)\n\n⑨向上述溶液中滴力口稀盐酸，搅拌后观察现象","explanation":"97.答案 D。\n\n摩尔质量是指1摩尔的某种物质的质量，即单位物质的量的物质所具有的质量，其单位为g/mol。在上述实验的化学反应中，有如下关系：参与反应的镁原子摩尔数=镁的质量/镁原子的摩尔质量参与反应的氧原子摩尔数=氧的质量/氧原子的摩尔质量即参与反应的镁的质量和参与反应的氧气的质量为m1、m2，若二者的摩尔质量分别为M1、M2，m1m2, n2= M2在镁原子摩尔数n1氧原子摩尔数n2已知的情况下，可确定在氧化镁分子中，镁原子与氧原子的原子个数比等于镁原子摩尔数与氧原子摩尔数之比，即n1：n2，原子个数比即为氧化镁的化学式计量比，由此可确定氧化镁的化学式。因此，必须补充的条件是②③。"},"from":{"file":"07-事业编职测/C类/2026/2026-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[31]},"idx":96,"pid":"p890e27c70b","sourceYears":[2026]},{"qid":"sy-c-20260329-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"加入酌献指示剂后，如果溶液未呈现浅红色，最可能的原因是( ) 。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[31,32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20260329-098-题目-p19-518-584.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2026-03-29-m96-材料-p19-130-416.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"侯带只燃烧了一部分"},{"k":"B","t":"滴加酌&amp;指示剂之前己滴加稀盐酸C 氧化镇粉末加水之前没有充分冷却"},{"k":"C","t":"C"},{"k":"D","t":"氧化镇粉末加水之后未充分搅拌均匀"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20260329-098-解析-p31-642-810.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20260329-098-解析-p32-50-154.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"加入酌献指示剂后，如果溶液未呈现浅红色，最可能的原因是( ) 。","options":[{"k":"A","t":"侯带只燃烧了一部分"},{"k":"B","t":"滴加酌&指示剂之前己滴加稀盐酸C 氧化镇粉末加水之前没有充分冷却"},{"k":"C","t":"C"},{"k":"D","t":"氧化镇粉末加水之后未充分搅拌均匀"}],"material":"材料五实验材料:电子天平、时娟、士甘蜗钳、酒精喷灯、玻璃棒、银子、烧杯、;高营、候带、稀盐酸、盼西k指示剂、 蒸情水实验步骤:\n\n①将士甘闲放在电子天平上称量，记录空时士写的质量\n\n②冷却后，用电子天平称量柑周和氧化锐的总质量\n\n③用电子天平称量一小段候带，记录质量\n\n④用酒精喷灯加热候带至完全燃烧\n\n⑤用链子将候带放入卅呐，再次称量，记录总质量\n\n⑥分析判断氧化锐的化学式\n\n⑦取少量氧化娱粉末，加入蒸馆水， 搅拌后观察是否溶解\n\n⑧滴力口盼酥指示剂，观察颜色变化(盼酥指示剂在酸性、中性环境中元色，在弱域性环境中主浅红色)\n\n⑨向上述溶液中滴力口稀盐酸，搅拌后观察现象","explanation":"98.答案B。\n\n实验中，氧化镁是碱性氧化物，与水反应生成氢氧化镁，溶液呈弱碱性→酚酞应呈浅红色。而酚酞未变红的核心原因是：溶液不是弱碱性（可能是酸性、中性，或酚酰未接触到碱性物质）。\n\nA项错误，即使镁带仅部分燃烧，生成的氧化镁仍会与水反应呈现弱碱性，溶液应呈现浅红色。\n\nB项正确，若滴加酚酞指示剂之前已滴加稀盐酸，稀盐酸会与氢氧化镁反应（中和），消耗掉碱，使溶液变成中性甚至酸性，酚酞不变色。这是最直接、最可能的原因。\n\nC项错误，温度高不影响氧化镁与水的反应，也不改变溶液碱性，酚酞仍会浅红。\n\nD项错误，若氧化镁粉末加水之后未充分搅拌均匀，可能会导致氧化镁粉末与水反应不充分，会有少量氧化镁固体残留在水中，但仍会有部分氧化镁与水反应生成氢氧化镁，溶液仍会呈碱性，不会出现完全不变色的情况。"},"from":{"file":"07-事业编职测/C类/2026/2026-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[31,32]},"idx":97,"pid":"p890e27c70b","sourceYears":[2026]},{"qid":"sy-c-20260329-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"在实验中，如果称量的氧化娱质量小于预期， 不可能的原因是( ) 。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20260329-099-题目-p19-579-686.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2026-03-29-m96-材料-p19-130-416.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"实验使用的镇带中有不易氧化的其他金属"},{"k":"B","t":"馍燃烧不充分，仍有部分金属模单质存留"},{"k":"C","t":"氧化模与空气中的二氧化碳反应生成碳酸镇"},{"k":"D","t":"燃烧中产生的氧化镇粉末被热空气带出甜塌"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20260329-099-解析-p32-150-387.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"在实验中，如果称量的氧化娱质量小于预期， 不可能的原因是( ) 。","options":[{"k":"A","t":"实验使用的镇带中有不易氧化的其他金属"},{"k":"B","t":"馍燃烧不充分，仍有部分金属模单质存留"},{"k":"C","t":"氧化模与空气中的二氧化碳反应生成碳酸镇"},{"k":"D","t":"燃烧中产生的氧化镇粉末被热空气带出甜塌"}],"material":"材料五实验材料:电子天平、时娟、士甘蜗钳、酒精喷灯、玻璃棒、银子、烧杯、;高营、候带、稀盐酸、盼西k指示剂、 蒸情水实验步骤:\n\n①将士甘闲放在电子天平上称量，记录空时士写的质量\n\n②冷却后，用电子天平称量柑周和氧化锐的总质量\n\n③用电子天平称量一小段候带，记录质量\n\n④用酒精喷灯加热候带至完全燃烧\n\n⑤用链子将候带放入卅呐，再次称量，记录总质量\n\n⑥分析判断氧化锐的化学式\n\n⑦取少量氧化娱粉末，加入蒸馆水， 搅拌后观察是否溶解\n\n⑧滴力口盼酥指示剂，观察颜色变化(盼酥指示剂在酸性、中性环境中元色，在弱域性环境中主浅红色)\n\n⑨向上述溶液中滴力口稀盐酸，搅拌后观察现象","explanation":"99. 答案 C。\n\n本题考查化学实验。=实验预期质量=镁带质量m+参加反应的氧气质量n，镁与氧气按化学计量比结合生成氧化镁。\n\nA项正确，若镁带中有不易氧化的金属，则这部分金属不反应，实际参加反应的镁质量m偏小，会导致参与反应的的氧气质量n偏小，最后生成的氧化镁质量偏小。\n\nB项正确，若镁燃烧不充分，同样会使实际参加反应的镁质量m偏小，会导致参与反应的氧气质量n偏小，最后生成的氧化镁质量偏小。\n\nC项错误，若氧化镁与二氧化碳反应生成碳酸镁（M.O+CO=M.CO），即在反应第一阶段结束后，反应生成的氧化镁又继续与二氧化碳反应，整个反应体系又增加了二氧化碳的质量。因此，这种情况下，生成物质量应该增加，而不是减少。\n\nD项正确，燃烧中产生的氧化镁粉末被热空气带出埚，即部分氧化镁流失，导致称量质量偏小。"},"from":{"file":"07-事业编职测/C类/2026/2026-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[32]},"idx":98,"pid":"p890e27c70b","sourceYears":[2026]},{"qid":"sy-c-20260329-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"如果燃烧过程未完成或者出现燃烧不充分的情况，可以采取的正确补救措施是( ) 。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20260329-100-题目-p19-682-806.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2026-03-29-m96-材料-p19-130-416.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"继续加热地塌中的镜带使其充分燃烧"},{"k":"B","t":"向燃烧后的氧化镜中加水后再次加热"},{"k":"C","t":"从瑞士目中取出未燃尽的镇带去除表面杂质"},{"k":"D","t":"去除镇带上未完全燃烧的残留物后直接计算"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20260329-100-解析-p32-382-806.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"如果燃烧过程未完成或者出现燃烧不充分的情况，可以采取的正确补救措施是( ) 。","options":[{"k":"A","t":"继续加热地塌中的镜带使其充分燃烧"},{"k":"B","t":"向燃烧后的氧化镜中加水后再次加热"},{"k":"C","t":"从瑞士目中取出未燃尽的镇带去除表面杂质"},{"k":"D","t":"去除镇带上未完全燃烧的残留物后直接计算"}],"material":"材料五实验材料:电子天平、时娟、士甘蜗钳、酒精喷灯、玻璃棒、银子、烧杯、;高营、候带、稀盐酸、盼西k指示剂、 蒸情水实验步骤:\n\n①将士甘闲放在电子天平上称量，记录空时士写的质量\n\n②冷却后，用电子天平称量柑周和氧化锐的总质量\n\n③用电子天平称量一小段候带，记录质量\n\n④用酒精喷灯加热候带至完全燃烧\n\n⑤用链子将候带放入卅呐，再次称量，记录总质量\n\n⑥分析判断氧化锐的化学式\n\n⑦取少量氧化娱粉末，加入蒸馆水， 搅拌后观察是否溶解\n\n⑧滴力口盼酥指示剂，观察颜色变化(盼酥指示剂在酸性、中性环境中元色，在弱域性环境中主浅红色)\n\n⑨向上述溶液中滴力口稀盐酸，搅拌后观察现象","explanation":"100.答案A。\n\nA项正确，燃烧过程未完成或者出现燃烧不充分的情况，可能是因为加热时间不足、温度不够高，或者生成的氧化膜暂时阻碍了氧气接触，但并未彻底阻止。继续加热时，温度进一步升高，氧化膜可能破裂或变得疏松，氧气可以继续与内部未反应的镁反应，最终使所有镁转化为氧化镁。\n\nB项错误，向燃烧后的氧化镁中加水后，由于水隔绝氧气且降低了温度，再次加热也很难使镁带充分燃烧，实验无法继续开展。\n\nC项错误，一般镁带燃烧实验会在实验开始前对镁带打磨，目的是除去镁带表面的杂质，提高反应活性。但本实验已经进行到一半，步骤③中也已经称量了镁带质量，此时去除杂质会使一部分质量流失；且此时镁带、氧化镁、杂质三者混合在一起，很难准确将三者区分开，去除杂质过程也很可能将镁或者氧化镁去除，使实验出现较大的数据失真。\n\nD项错误，实验的关键就是测量反应前后反应物的质量变化，去除镁带上未完全燃烧的残留物后直接计算，会导致反应生成物的测量值偏小，实验数据无效。"},"from":{"file":"07-事业编职测/C类/2026/2026-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[32]},"idx":99,"pid":"p890e27c70b","sourceYears":[2026]},{"qid":"sy-c-20250329-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"以下哪项，是（1）中最为合适的实验步骤？（）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-096-题目-p23-460-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-03-29-m96-材料-p23-70-460.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"③②④⑤①"},{"k":"B","t":"③⑤②①④"},{"k":"C","t":"④⑤②③①"},{"k":"D","t":"④②③①⑤"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-096-解析-p30-304-480.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下哪项，是（1）中最为合适的实验步骤？（）","options":[{"k":"A","t":"③②④⑤①"},{"k":"B","t":"③⑤②①④"},{"k":"C","t":"④⑤②③①"},{"k":"D","t":"④②③①⑤"}],"material":"（五）实验材料：（1）5%卵清蛋白质溶液，蒸馏水；\n\n（2）试管，试管架，移液器，滴管；\n\n（3）试剂：①3%硝酸银溶液，②3%三氯乙酸溶液，③95%乙醇，④硫酸铵结晶粉末，⑤饱和硫酸铵溶液。\n\n实验步骤：（1）蛋白质的盐析。\n\n①取出部分清蛋白于另一试管中，加入少量蒸馏水，观察沉淀的再溶解情况。\n\n②倒出少量沉淀于另一试管中，加少量水，观察是否溶解。\n\n③将试管内不溶物过滤，向滤液中添加硫酸铵粉末直到不再溶解为止，混匀、静置，观察沉淀反应，这时析出的是清蛋白。\n\n④加5%卵清蛋白质溶液5ml 于一支试管中。\n\n⑤再加等量的饱和硫酸铵溶液，混匀后静置数分钟观察沉淀反应，此时析出的是球蛋白。\n\n（2）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%硝酸银溶液1～2 滴，振荡试管，静置，观察沉淀物的产生。\n\n（3）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%三氯乙酸溶液1ml，振荡试管，静置，观察沉淀物的产生。\n\n（4）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入95%乙醇2ml，混匀，静置，观察沉淀物的产生。\n\n实验说明：蛋白质分为球蛋白、清蛋白、谷蛋白等。蛋白质分子在水溶液中由于表面生成水化层和双电层而形成一种稳定的亲水胶体颗粒，在水溶液中，在胶体颗粒之外包含有一层水膜，水膜可以把各个颗粒相互隔开，所以水溶液中的胶体颗粒不会凝聚成块而下沉。但是，在一定的理化条件下，蛋白质分子胶体颗粒平衡会被打破，凝聚为沉淀。蛋白质的沉淀其实就是蛋白质分子聚集，使得它从溶液中析出的一种现象。","explanation":"96\n\n本题考查化学实验。\n\n观察选项，步骤④为向试管中添加蛋白质溶液，属于实验必须的起始操作，应当在步骤③之前，排除A、\n\nB项。\n\n继续观察C、D项，步骤②为倒出沉淀并加水溶解，而步骤③为加入加饱和硫酸铵溶液，根据蛋白质盐析原理，应先加入盐溶液，才会产生沉淀，故步骤③在步骤②之前，排除D项。\n\n继续验证C项：步骤③为过滤去除球蛋白后，向滤液中继续加硫酸铵粉末至饱和，这时会析出清蛋白，完成蛋白质的分级盐析；步骤①为验证清蛋白沉淀的溶解性，确认盐析的可逆性。\n\n另，盐析需先析出低盐浓度的球蛋白，再通过高盐析出清蛋白，根据这一顺序也可判断步骤③在步骤\n\n③之前，得出正确步骤。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[30]},"idx":95,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-c-20250329-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"本实验的目的是（）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-097-题目-p23-553-651.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-03-29-m96-材料-p23-70-460.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"了解沉淀蛋白质的方法"},{"k":"B","t":"了解沉淀蛋白质的原理"},{"k":"C","t":"了解沉淀蛋白质的步骤"},{"k":"D","t":"了解沉淀蛋白质的构成"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-097-解析-p30-475-620.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"本实验的目的是（）。","options":[{"k":"A","t":"了解沉淀蛋白质的方法"},{"k":"B","t":"了解沉淀蛋白质的原理"},{"k":"C","t":"了解沉淀蛋白质的步骤"},{"k":"D","t":"了解沉淀蛋白质的构成"}],"material":"（五）实验材料：（1）5%卵清蛋白质溶液，蒸馏水；\n\n（2）试管，试管架，移液器，滴管；\n\n（3）试剂：①3%硝酸银溶液，②3%三氯乙酸溶液，③95%乙醇，④硫酸铵结晶粉末，⑤饱和硫酸铵溶液。\n\n实验步骤：（1）蛋白质的盐析。\n\n①取出部分清蛋白于另一试管中，加入少量蒸馏水，观察沉淀的再溶解情况。\n\n②倒出少量沉淀于另一试管中，加少量水，观察是否溶解。\n\n③将试管内不溶物过滤，向滤液中添加硫酸铵粉末直到不再溶解为止，混匀、静置，观察沉淀反应，这时析出的是清蛋白。\n\n④加5%卵清蛋白质溶液5ml 于一支试管中。\n\n⑤再加等量的饱和硫酸铵溶液，混匀后静置数分钟观察沉淀反应，此时析出的是球蛋白。\n\n（2）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%硝酸银溶液1～2 滴，振荡试管，静置，观察沉淀物的产生。\n\n（3）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%三氯乙酸溶液1ml，振荡试管，静置，观察沉淀物的产生。\n\n（4）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入95%乙醇2ml，混匀，静置，观察沉淀物的产生。\n\n实验说明：蛋白质分为球蛋白、清蛋白、谷蛋白等。蛋白质分子在水溶液中由于表面生成水化层和双电层而形成一种稳定的亲水胶体颗粒，在水溶液中，在胶体颗粒之外包含有一层水膜，水膜可以把各个颗粒相互隔开，所以水溶液中的胶体颗粒不会凝聚成块而下沉。但是，在一定的理化条件下，蛋白质分子胶体颗粒平衡会被打破，凝聚为沉淀。蛋白质的沉淀其实就是蛋白质分子聚集，使得它从溶液中析出的一种现象。","explanation":"97\n\n本题考查化学实验。\n\nA项正确，C项错误，实验通过盐析、重金属盐、有机酸、有机溶剂四种方法沉淀蛋白质，直接对应“沉淀蛋白质的方法”。\n\nB项错误，实验材料中已在“实验说明”部分解释了沉淀蛋白质的原理，故并非本实验的目的。\n\nC项错误，“沉淀蛋白质的步骤”不够全面，实验中只有第一种方法“盐析”有较为详细的步骤，而重金属盐、有机酸、有机溶等三种沉淀方法并不涉及实验步骤层面。\n\n芹具题库\n\nD项错误，本实验并未涉及蛋白质结构分析。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[30]},"idx":96,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-c-20250329-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（1）盐类；（2）金属离子；（3）有机酸；（4）有机溶剂","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[30,31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-098-题目-p23-647-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20250329-098-题目-p24-51-74.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-03-29-m96-材料-p23-70-460.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"仅（1）（2）"},{"k":"B","t":"仅（3）（4）"},{"k":"C","t":"仅（2）（3）（4）"},{"k":"D","t":"（1）（2）（3）（4）"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-098-解析-p30-616-735.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20250329-098-解析-p31-46-184.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"影响蛋白质胶体水溶液稳定的因素主要有（）。\n\n（1）盐类；（2）金属离子；（3）有机酸；（4）有机溶剂","options":[{"k":"A","t":"仅（1）（2）"},{"k":"B","t":"仅（3）（4）"},{"k":"C","t":"仅（2）（3）（4）"},{"k":"D","t":"（1）（2）（3）（4）"}],"material":"（五）实验材料：（1）5%卵清蛋白质溶液，蒸馏水；\n\n（2）试管，试管架，移液器，滴管；\n\n（3）试剂：①3%硝酸银溶液，②3%三氯乙酸溶液，③95%乙醇，④硫酸铵结晶粉末，⑤饱和硫酸铵溶液。\n\n实验步骤：（1）蛋白质的盐析。\n\n①取出部分清蛋白于另一试管中，加入少量蒸馏水，观察沉淀的再溶解情况。\n\n②倒出少量沉淀于另一试管中，加少量水，观察是否溶解。\n\n③将试管内不溶物过滤，向滤液中添加硫酸铵粉末直到不再溶解为止，混匀、静置，观察沉淀反应，这时析出的是清蛋白。\n\n④加5%卵清蛋白质溶液5ml 于一支试管中。\n\n⑤再加等量的饱和硫酸铵溶液，混匀后静置数分钟观察沉淀反应，此时析出的是球蛋白。\n\n（2）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%硝酸银溶液1～2 滴，振荡试管，静置，观察沉淀物的产生。\n\n（3）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%三氯乙酸溶液1ml，振荡试管，静置，观察沉淀物的产生。\n\n（4）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入95%乙醇2ml，混匀，静置，观察沉淀物的产生。\n\n实验说明：蛋白质分为球蛋白、清蛋白、谷蛋白等。蛋白质分子在水溶液中由于表面生成水化层和双电层而形成一种稳定的亲水胶体颗粒，在水溶液中，在胶体颗粒之外包含有一层水膜，水膜可以把各个颗粒相互隔开，所以水溶液中的胶体颗粒不会凝聚成块而下沉。但是，在一定的理化条件下，蛋白质分子胶体颗粒平衡会被打破，凝聚为沉淀。蛋白质的沉淀其实就是蛋白质分子聚集，使得它从溶液中析出的一种现象。","explanation":"98\n\n本题考查化学实验。\n\n（1）正确，在蛋白质溶液中加人一定浓度的强电解质盐，如（NH4)2SO、Na2SO4、NaCI、MgSO等，蛋白质从溶液中析出，这种作用称为盐析。盐析作用的实质是高浓度的强电解质破坏蛋白质分子表面的水化膜，同时电解质离子中和蛋白质所带的电荷，蛋白质的稳定因素被消除，使蛋白质分子相互碰撞而凝聚沉淀。\n\n（2）（3）正确，蛋白质溶液中加入重金属盐（如汞盐、铅盐等）、某些有机酸等其他有机试剂（如如苯酚、甲醛、三氯乙酸、丹宁酸、苦味酸及尿素等）生物碱试剂、酸性或碱性染料等或使蛋白质受到加热、干燥、高频振荡、超声波、紫外光照射等物理作用，可以使蛋白质性质改变，溶解度降低而凝聚出来。\n\n这种凝聚是不可逆的，它使蛋白质的空间构象遭到破坏、失去原有理化性质和生理活性，使蛋白质变性，空间结构发生变化。\n\n（4）正确，在蛋白质水溶液中乙醇或丙酮等改变溶液的极性，引起蛋白质脱去水化层以及降低介电常数而增加异性电荷间的相互作用，导致蛋白质颗粒容易聚集而沉淀。\n\n综上所述，（1）（2）（3）（4）都属于影响蛋白质胶体水溶液稳定的主要因素。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[30,31]},"idx":97,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-c-20250329-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（1）稀释；（2）失去电荷；（3）脱水；（4）震荡","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[24],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-099-题目-p24-70-183.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-03-29-m96-材料-p23-70-460.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"（1）（2）"},{"k":"B","t":"（2）（3）"},{"k":"C","t":"（2）（4）"},{"k":"D","t":"（3）（4）"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-099-解析-p31-179-340.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"从本实验可以得知，蛋白质分子可以因为如下因素而沉淀（）。\n\n（1）稀释；（2）失去电荷；（3）脱水；（4）震荡","options":[{"k":"A","t":"（1）（2）"},{"k":"B","t":"（2）（3）"},{"k":"C","t":"（2）（4）"},{"k":"D","t":"（3）（4）"}],"material":"（五）实验材料：（1）5%卵清蛋白质溶液，蒸馏水；\n\n（2）试管，试管架，移液器，滴管；\n\n（3）试剂：①3%硝酸银溶液，②3%三氯乙酸溶液，③95%乙醇，④硫酸铵结晶粉末，⑤饱和硫酸铵溶液。\n\n实验步骤：（1）蛋白质的盐析。\n\n①取出部分清蛋白于另一试管中，加入少量蒸馏水，观察沉淀的再溶解情况。\n\n②倒出少量沉淀于另一试管中，加少量水，观察是否溶解。\n\n③将试管内不溶物过滤，向滤液中添加硫酸铵粉末直到不再溶解为止，混匀、静置，观察沉淀反应，这时析出的是清蛋白。\n\n④加5%卵清蛋白质溶液5ml 于一支试管中。\n\n⑤再加等量的饱和硫酸铵溶液，混匀后静置数分钟观察沉淀反应，此时析出的是球蛋白。\n\n（2）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%硝酸银溶液1～2 滴，振荡试管，静置，观察沉淀物的产生。\n\n（3）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%三氯乙酸溶液1ml，振荡试管，静置，观察沉淀物的产生。\n\n（4）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入95%乙醇2ml，混匀，静置，观察沉淀物的产生。\n\n实验说明：蛋白质分为球蛋白、清蛋白、谷蛋白等。蛋白质分子在水溶液中由于表面生成水化层和双电层而形成一种稳定的亲水胶体颗粒，在水溶液中，在胶体颗粒之外包含有一层水膜，水膜可以把各个颗粒相互隔开，所以水溶液中的胶体颗粒不会凝聚成块而下沉。但是，在一定的理化条件下，蛋白质分子胶体颗粒平衡会被打破，凝聚为沉淀。蛋白质的沉淀其实就是蛋白质分子聚集，使得它从溶液中析出的一种现象。","explanation":"99\n\n本题考查化学实验。\n\n（1）错误，实验中未稀释蛋白质溶液，盐析需高盐浓度，稀释可能溶解盐析出的沉淀，非沉淀原因。\n\n（2）正确，当溶液pH大于等电点时，蛋白质颗粒带负电荷，容易与重金属离子结合成不溶性盐而沉淀。硝酸银（Ag）中和蛋白质负电荷，消除双电层稳定性，导致沉淀。\n\n（3）正确，乙醇等极性溶剂会引起蛋白质脱去水化层以及降低介电常数而增加异性电荷间的相互作用，导致蛋白质颗粒容易聚集而沉淀。\n\n（4）错误，实验中并未对蛋白质溶液进行震荡，故无法根据上述实验得出。\n\n综上所述，蛋白质分子可以因为（2）失去电荷、（3）脱水而沉淀。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[24],"answerPages":[31]},"idx":98,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-c-20250329-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"本实验运用的主要探究方法是（）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[24],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-100-题目-p24-179-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-03-29-m96-材料-p23-70-460.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"求同法"},{"k":"B","t":"剩余法"},{"k":"C","t":"共变法"},{"k":"D","t":"差异法"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-100-解析-p31-336-731.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"本实验运用的主要探究方法是（）。","options":[{"k":"A","t":"求同法"},{"k":"B","t":"剩余法"},{"k":"C","t":"共变法"},{"k":"D","t":"差异法"}],"material":"（五）实验材料：（1）5%卵清蛋白质溶液，蒸馏水；\n\n（2）试管，试管架，移液器，滴管；\n\n（3）试剂：①3%硝酸银溶液，②3%三氯乙酸溶液，③95%乙醇，④硫酸铵结晶粉末，⑤饱和硫酸铵溶液。\n\n实验步骤：（1）蛋白质的盐析。\n\n①取出部分清蛋白于另一试管中，加入少量蒸馏水，观察沉淀的再溶解情况。\n\n②倒出少量沉淀于另一试管中，加少量水，观察是否溶解。\n\n③将试管内不溶物过滤，向滤液中添加硫酸铵粉末直到不再溶解为止，混匀、静置，观察沉淀反应，这时析出的是清蛋白。\n\n④加5%卵清蛋白质溶液5ml 于一支试管中。\n\n⑤再加等量的饱和硫酸铵溶液，混匀后静置数分钟观察沉淀反应，此时析出的是球蛋白。\n\n（2）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%硝酸银溶液1～2 滴，振荡试管，静置，观察沉淀物的产生。\n\n（3）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入3%三氯乙酸溶液1ml，振荡试管，静置，观察沉淀物的产生。\n\n（4）取干净试管一支，加入5%卵清蛋白质溶液2ml，再加入95%乙醇2ml，混匀，静置，观察沉淀物的产生。\n\n实验说明：蛋白质分为球蛋白、清蛋白、谷蛋白等。蛋白质分子在水溶液中由于表面生成水化层和双电层而形成一种稳定的亲水胶体颗粒，在水溶液中，在胶体颗粒之外包含有一层水膜，水膜可以把各个颗粒相互隔开，所以水溶液中的胶体颗粒不会凝聚成块而下沉。但是，在一定的理化条件下，蛋白质分子胶体颗粒平衡会被打破，凝聚为沉淀。蛋白质的沉淀其实就是蛋白质分子聚集，使得它从溶液中析出的一种现象。","explanation":"100\n\n本题考查化学实验。\n\nA项错误，求同法是指寻找不同现象的共同原因（如多种试剂均导致沉淀的共同原因），上述实验中并未归纳共同原因，而是对比不同方法的差异。\n\nB项错误，剩余法是指排除已知因素后推断剩余原因，实验未涉及排除变量。\n\nC项错误，共变法是在一定的条件下，对所有组进行相同的处理，然后观察因变量的变化并与实验前作比较，即共变法只有一个自变量，而实验中是对不同组采用了不同的处理，存在多个自变量。\n\nD项正确，差异法是改变单一变量（试剂类型），观察结果差异。上述实验中，通过盐析、重金属、有机酸、乙醇四种不同条件，对比沉淀现象的差异，总结沉淀规律，利用了差异法。\n\n故正确答案为D。\n\n口岸真题库了扫描二维码，可获取更多免费公考资料"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[24],"answerPages":[31]},"idx":99,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-c-20251025-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"上述实验步骤（2）～（7）是被打乱的，正确的实验步骤应为（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[18],"answer":[45,46]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-096-题目-p18-368-427.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m96-材料-p18-120-368.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"（2）（4）（3）（7）（5）（6）"},{"k":"B","t":"（2）（6）（4）（3）（7）（5）"},{"k":"C","t":"（4）（3）（2）（7）（6）（5）"},{"k":"D","t":"（4）（6）（2）（7）（5）（3）"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-096-解析-p45-598-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-096-解析-p46-51-199.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"上述实验步骤（2）～（7）是被打乱的，正确的实验步骤应为（    ）。","options":[{"k":"A","t":"（2）（4）（3）（7）（5）（6）"},{"k":"B","t":"（2）（6）（4）（3）（7）（5）"},{"k":"C","t":"（4）（3）（2）（7）（6）（5）"},{"k":"D","t":"（4）（6）（2）（7）（5）（3）"}],"material":"（二）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理选出最符合每道题要求的一项。\n\n（—）实验目的：用硬币测量表面张力实验材料：硬币、滴管、小碗、自来水、肥皂、纸巾实验步骤：（1）把硬币放在一个水平的表面上。\n\n（2）在小碗中倒入自来水。\n\n（3）小心地在硬币顶部一次加一滴水。\n\n（4）将滴管放在硬币正上方并不要碰到硬币。\n\n（5）用纸巾彻底擦干硬币和周围表面。\n\n（6）用滴管吸取小碗中的水。\n\n（7）观察水滴，在水溢出硬币边缘时对滴落的水滴进行计数。\n\n（8）将少量的肥皂与自来水混合，用肥皂水重复实验并对比两个计数。","explanation":"96\n\n本题考查物理实验。\n\n步骤（2）“在小碗中倒入自来水”——这是实验的基础准备，必须最先进行（没有水，后续吸水、滴加都无法完成），排除C、D 项。\n\n对比步骤（4）和（6），步骤（4）是将滴管放在硬币正上方，步骤（6）是用滴管吸取小碗中的水，应当先吸取水，才能进行后续实验步骤，故步骤（6）不可能是最后一步，应当紧跟在步骤（2）之后，排除A 项。\n\n验证后续实验步骤：步骤（6）吸取水后，再进行步骤（4）调整滴管位置，步骤（3）开始滴水，步骤（7）是滴水后进入观察和计数环节，步骤（5）实验结束，清理硬币，为后续重复实验（如用肥皂水）做准备。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[18],"answerPages":[45,46]},"idx":95,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20251025-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"的计数相同，则最有可能是（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[18],"answer":[46]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-097-题目-p18-423-760.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m96-材料-p18-120-368.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"肥皂水中含有其他的杂质"},{"k":"B","t":"水中含有与肥皂类似的杂质"},{"k":"C","t":"用水做实验后硬币未彻底干燥"},{"k":"D","t":"硬币未放置在绝对水平的表面上"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-097-解析-p46-195-486.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"已知肥皂水的表面张力和水存在较大差异，在用肥皂水做实验时，如果步骤（7）得出的计数与用水做实验时的计数相同，则最有可能是（    ）。","options":[{"k":"A","t":"肥皂水中含有其他的杂质"},{"k":"B","t":"水中含有与肥皂类似的杂质"},{"k":"C","t":"用水做实验后硬币未彻底干燥"},{"k":"D","t":"硬币未放置在绝对水平的表面上"}],"material":"（二）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理选出最符合每道题要求的一项。\n\n（—）实验目的：用硬币测量表面张力实验材料：硬币、滴管、小碗、自来水、肥皂、纸巾实验步骤：（1）把硬币放在一个水平的表面上。\n\n（2）在小碗中倒入自来水。\n\n（3）小心地在硬币顶部一次加一滴水。\n\n（4）将滴管放在硬币正上方并不要碰到硬币。\n\n（5）用纸巾彻底擦干硬币和周围表面。\n\n（6）用滴管吸取小碗中的水。\n\n（7）观察水滴，在水溢出硬币边缘时对滴落的水滴进行计数。\n\n（8）将少量的肥皂与自来水混合，用肥皂水重复实验并对比两个计数。","explanation":"97\n\n本题考查物理实验。\n\nA、B 项错误，杂质可能增大或降低液体的表面张力，选项并未明确是何种杂质，因此加入杂质后并不能确定液体表面张力的变化方向，既有可能增大，也有可能减小，属于可能性较低的猜测。\n\nC 项正确，假设水的表面张力是m，肥皂水的表面张力是n。若用水做实验后硬币未彻底干燥，残留的水会稀释后续的肥皂水，使其表面张力介于m 和n 之间，即趋近于水的表面张力，从而导致两者能承载的水滴数接近，计数相同。\n\nD 项错误，硬币未放置在绝对水平的表面上可能会影响实验中硬币承载的水滴数，但这对于对照试验（肥皂水组）的影响同样存在的，不会造成两组实验计数相同。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[18],"answerPages":[46]},"idx":96,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20251025-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"上述实验步骤（1）—（5）是被打乱的，正确的实验步骤应为（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[18,19],"answer":[46]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-098-题目-p18-755-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-098-题目-p19-51-126.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m98-材料-p18-491-755.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"（1）（4）（5）（3）（2）"},{"k":"B","t":"（3）（5）（1）（2）（4）"},{"k":"C","t":"（4）（5）（3）（1）（2）"},{"k":"D","t":"（5）（3）（4）（1）（2）"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-098-解析-p46-482-709.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"上述实验步骤（1）—（5）是被打乱的，正确的实验步骤应为（    ）。","options":[{"k":"A","t":"（1）（4）（5）（3）（2）"},{"k":"B","t":"（3）（5）（1）（2）（4）"},{"k":"C","t":"（4）（5）（3）（1）（2）"},{"k":"D","t":"（5）（3）（4）（1）（2）"}],"material":"（三）实验材料与器材：双凹载玻片、消毒牙签、刺血针、A型和B型标准血清、生理盐水、酒精棉球、显微镜实验原理：根据红细胞膜外表面是否存在特异性的抗原A或B，将人的血型分为A、B、AB、O四个类型，A型血中红细胞表面含有A抗原，血清里含有B抗体；B型血中红细胞表面含有B抗原，血清里含有A抗体。当抗体与相应抗原起反应时，红细胞发生凝集，最后溶解，为了避免这一点，确保安全输血，临床上输血前必须鉴定血型，一般血型相同才能输血。\n\n实验步骤：（1）穿刺被试手指取血，玻片的a、b两侧各放入一小滴血，用牙签搅拌，使每侧标准血清和血液混合，每侧用一支牙签，切勿混用。\n\n（2）室温下静置10-15分钟，观察有无凝集现象。若只是a侧发生凝集，则血型为A型；若只是b侧发生凝集，则血型为B型；若两侧均未凝集，则为O型；若两侧均发生凝集，则为AB型。\n\n（3）用另一个小滴管吸B型标准血清一滴加入左侧。\n\n（4）取一块清洁玻片，用笔做记号，左上角写a字，右上角写b字。\n\n（5）用小滴管吸A型标准血清一滴加入右侧。","explanation":"98\n\n本题考查生物实验。\n\n步骤（1）在玻片两侧放入血液，并使血液与血清混合，因此在步骤（1）之前，玻片中应先滴入血清，观察实验步骤，步骤（3）和步骤（5）是向玻片中滴入血清，因此步骤（3）（5）在步骤（1）之前，且由步骤（3）（5）中的“用小滴管”“用另一个小滴管”可知步骤（5）在（3）之前，排除A、B 项。\n\n步骤（4）是对玻片做记号，应当是先对玻片做记号，这是实验的准备工作，再进行实验其他操作，故（4）在（5）之前，排除D 项。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[18,19],"answerPages":[46]},"idx":97,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20251025-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"以下哪项最可能是本实验的目的？（    ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[46,47]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-099-题目-p19-122-181.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m98-材料-p18-491-755.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"掌握血型的鉴定方法和原理"},{"k":"B","t":"检验不同血型的输血安全性"},{"k":"C","t":"探寻不同血型的抗原和抗体"},{"k":"D","t":"观察红细胞的凝集现象和时长"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-099-解析-p46-705-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-099-解析-p47-51-367.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下哪项最可能是本实验的目的？（    ）","options":[{"k":"A","t":"掌握血型的鉴定方法和原理"},{"k":"B","t":"检验不同血型的输血安全性"},{"k":"C","t":"探寻不同血型的抗原和抗体"},{"k":"D","t":"观察红细胞的凝集现象和时长"}],"material":"（三）实验材料与器材：双凹载玻片、消毒牙签、刺血针、A型和B型标准血清、生理盐水、酒精棉球、显微镜实验原理：根据红细胞膜外表面是否存在特异性的抗原A或B，将人的血型分为A、B、AB、O四个类型，A型血中红细胞表面含有A抗原，血清里含有B抗体；B型血中红细胞表面含有B抗原，血清里含有A抗体。当抗体与相应抗原起反应时，红细胞发生凝集，最后溶解，为了避免这一点，确保安全输血，临床上输血前必须鉴定血型，一般血型相同才能输血。\n\n实验步骤：（1）穿刺被试手指取血，玻片的a、b两侧各放入一小滴血，用牙签搅拌，使每侧标准血清和血液混合，每侧用一支牙签，切勿混用。\n\n（2）室温下静置10-15分钟，观察有无凝集现象。若只是a侧发生凝集，则血型为A型；若只是b侧发生凝集，则血型为B型；若两侧均未凝集，则为O型；若两侧均发生凝集，则为AB型。\n\n（3）用另一个小滴管吸B型标准血清一滴加入左侧。\n\n（4）取一块清洁玻片，用笔做记号，左上角写a字，右上角写b字。\n\n（5）用小滴管吸A型标准血清一滴加入右侧。","explanation":"99\n\n本题考查生物实验。\n\nA 项正确，实验原理明确“根据红细胞抗原与血清抗体的凝集反应分血型”，步骤是“加标准血判断血型”（如a 侧凝集为A 型），结果判断直接指向“鉴定血型”，清加血看凝集整个实验围绕“如何用标准血清鉴定血型”展开，同时体现了“抗原抗体反应”的原理，符合实验核心目的。\n\nB 项错误，该实验仅能鉴定单一血样类型，并未进行不同血型间的交叉配血实验，无法直接检验输血安全性。\n\nC 项错误，实验原理已明确给出“A 型血有A 抗原、B 抗体；B 型血有B 抗原、A 抗体”，属于“已知原理的应用”，而非“未知抗原抗体的探寻”。\n\nD 项错误，虽然实验中会观察凝集现象，但这只是达成“鉴定血型”目的的手段和过程，而非实验的根本目的。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[46,47]},"idx":98,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20251025-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"根据上述实验，可知AB型血清中（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[47]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-100-题目-p19-176-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m98-材料-p18-491-755.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"既含有A抗体又含有B抗体"},{"k":"B","t":"含有A抗体但不含B抗体"},{"k":"C","t":"含有B抗体但不含A抗体"},{"k":"D","t":"既不含A抗体也不含B抗体"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-100-解析-p47-363-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"根据上述实验，可知AB型血清中（    ）。","options":[{"k":"A","t":"既含有A抗体又含有B抗体"},{"k":"B","t":"含有A抗体但不含B抗体"},{"k":"C","t":"含有B抗体但不含A抗体"},{"k":"D","t":"既不含A抗体也不含B抗体"}],"material":"（三）实验材料与器材：双凹载玻片、消毒牙签、刺血针、A型和B型标准血清、生理盐水、酒精棉球、显微镜实验原理：根据红细胞膜外表面是否存在特异性的抗原A或B，将人的血型分为A、B、AB、O四个类型，A型血中红细胞表面含有A抗原，血清里含有B抗体；B型血中红细胞表面含有B抗原，血清里含有A抗体。当抗体与相应抗原起反应时，红细胞发生凝集，最后溶解，为了避免这一点，确保安全输血，临床上输血前必须鉴定血型，一般血型相同才能输血。\n\n实验步骤：（1）穿刺被试手指取血，玻片的a、b两侧各放入一小滴血，用牙签搅拌，使每侧标准血清和血液混合，每侧用一支牙签，切勿混用。\n\n（2）室温下静置10-15分钟，观察有无凝集现象。若只是a侧发生凝集，则血型为A型；若只是b侧发生凝集，则血型为B型；若两侧均未凝集，则为O型；若两侧均发生凝集，则为AB型。\n\n（3）用另一个小滴管吸B型标准血清一滴加入左侧。\n\n（4）取一块清洁玻片，用笔做记号，左上角写a字，右上角写b字。\n\n（5）用小滴管吸A型标准血清一滴加入右侧。","explanation":"100\n\n本题考查生物实验。\n\n实验步骤（2）说明，若为AB 型血，则两侧（a 侧为B 型标准血清——含有A 抗体，b 侧为A 型标准血清——含有B 抗体）均会发生凝集。这说明AB 型血的红细胞既与A 抗体反应，也与B 抗体反应，证明其红细胞上同时存在A 抗原和B 抗原。根据免疫学原理，人体不会产生对抗自身红细胞抗原的抗体。因此，AB 型血的血清中既不含有抗A 抗体，也不含有抗B 抗体。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[47]},"idx":99,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20240330-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"这项实验的研究结果显示了（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[16],"answer":[46]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20240330-096-题目-p16-467-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-03-30-m96-材料-p16-267-467.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"幼儿能够通过学习的方法来理解他人的情绪反应"},{"k":"B","t":"不同性别、年龄的幼儿理解他人情绪反应的必要条件"},{"k":"C","t":"无法准确判断幼儿能否根据他人情绪反应来推测其喜好"},{"k":"D","t":"幼儿在什么年龄获得根据他人情绪反应推测其喜好的能力"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20240330-096-解析-p46-298-443.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"这项实验的研究结果显示了（ ）。","options":[{"k":"A","t":"幼儿能够通过学习的方法来理解他人的情绪反应"},{"k":"B","t":"不同性别、年龄的幼儿理解他人情绪反应的必要条件"},{"k":"C","t":"无法准确判断幼儿能否根据他人情绪反应来推测其喜好"},{"k":"D","t":"幼儿在什么年龄获得根据他人情绪反应推测其喜好的能力"}],"material":"（二）实验对象：14个月和18个月大的幼儿各若干名，男孩和女孩均各占一半。\n\n实验材料：蔬菜和饼干若干。\n\n实验程序：幼儿被随机分成A、B两组。实验开始后，主试向幼儿提供蔬菜和饼干，在A组情境中，主试表现出喜欢吃饼干，而不喜欢吃蔬菜。在B组情境中，主试表现出喜欢吃蔬菜，但不喜欢吃饼干。此后，实验者要求幼儿向主试分享自己手中的蔬菜或饼干。\n\n实验结果：\n\nA、B两组中14个月大的幼儿无法理解主试的偏好，他们大都将自己喜欢吃的饼干分享给主试。A组中绝大部分18个月大的幼儿向主试分享自己手中的饼干。B组中绝大部分18个月大的幼儿向主试分享自己手中的蔬菜。","explanation":"96、本题考查心理学实验。\n\n在实验中最主要体现出的变量。一是婴儿分为14 个月和18 个月两个年龄段；二是A、B 两组的主试分别表现出对于不同食物的喜好。最后的实验结果体现出，18 个月大的幼儿可以感觉出主试的喜好，但是14 个月大的幼儿却不可以。因此，本实验结果显示了幼儿在什么年龄获得根据他人情绪反应推测其喜好的能力。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2024/2024-03-30/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[16],"answerPages":[46]},"idx":95,"pid":"p3f16ff5043","sourceYears":[2024]},{"qid":"sy-c-20240330-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"②用不同类型的食物重复实验","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[16,17],"answer":[46]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20240330-097-题目-p16-553-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20240330-097-题目-p17-51-159.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-03-30-m96-材料-p16-267-467.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"仅①能"},{"k":"B","t":"仅②能"},{"k":"C","t":"①和②都能"},{"k":"D","t":"①和②都不能"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20240330-097-解析-p46-438-630.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列两项措施中，（ ）使实验结果更为准确。\n\n①用3岁和5岁的幼儿作为实验对象重复该实验\n\n②用不同类型的食物重复实验","options":[{"k":"A","t":"仅①能"},{"k":"B","t":"仅②能"},{"k":"C","t":"①和②都能"},{"k":"D","t":"①和②都不能"}],"material":"（二）实验对象：14个月和18个月大的幼儿各若干名，男孩和女孩均各占一半。\n\n实验材料：蔬菜和饼干若干。\n\n实验程序：幼儿被随机分成A、B两组。实验开始后，主试向幼儿提供蔬菜和饼干，在A组情境中，主试表现出喜欢吃饼干，而不喜欢吃蔬菜。在B组情境中，主试表现出喜欢吃蔬菜，但不喜欢吃饼干。此后，实验者要求幼儿向主试分享自己手中的蔬菜或饼干。\n\n实验结果：\n\nA、B两组中14个月大的幼儿无法理解主试的偏好，他们大都将自己喜欢吃的饼干分享给主试。A组中绝大部分18个月大的幼儿向主试分享自己手中的饼干。B组中绝大部分18个月大的幼儿向主试分享自己手中的蔬菜。","explanation":"97、本题考查心理学实验。\n\n首先，在本实验结果中，已经体现出了18 个月大幼儿，对于他人情绪反应推测其喜好的能力，更大年龄的幼儿势必也大概率会具有此种能力。所以3 岁和5岁的幼儿，并不能很好的体现出区别，可能会导致实验失败，①改进不合理。\n\n其次，本实验中的食物种类较少，不能很好地排除幼儿个人喜好的影响。用不同类型的食物重复实验，可以更好体现出主试的情绪引导对于幼儿的作用，所以②改进可以使实验结果更为准确。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2024/2024-03-30/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[16,17],"answerPages":[46]},"idx":96,"pid":"p3f16ff5043","sourceYears":[2024]},{"qid":"sy-c-20240330-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"上述实验步骤的顺序是错乱的，以下哪项是最为合适的实验步骤？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[17],"answer":[46,47]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20240330-098-题目-p17-154-197.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-03-30-m98-材料-p16-622-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2024-03-30-m98-材料-p17-51-154.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"②⑤①⑥④③⑦"},{"k":"B","t":"③⑥②⑤①④⑦"},{"k":"C","t":"④②③⑤①⑥⑦"},{"k":"D","t":"⑤①④③⑥②⑦"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20240330-098-解析-p46-626-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20240330-098-解析-p47-51-160.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"上述实验步骤的顺序是错乱的，以下哪项是最为合适的实验步骤？（ ）","options":[{"k":"A","t":"②⑤①⑥④③⑦"},{"k":"B","t":"③⑥②⑤①④⑦"},{"k":"C","t":"④②③⑤①⑥⑦"},{"k":"D","t":"⑤①④③⑥②⑦"}],"material":"（三）实验材料：2个盘子、2个玻璃碗、1个装满水的喷雾瓶，餐巾纸、食醋、菜籽若干。\n\n实验步骤：\n\n①把玻璃碗分别扣在两个盘子上\n\n②同样将第二个盘子的纸巾喷水打湿，并在纸巾上加入食醋\n\n③在两个盘子上分别铺上餐巾纸\n\n④把两个盘子移到温暖有光照的地方\n\n⑤把菜籽均匀地撒在两个盘子的纸巾上\n\n⑥用喷雾瓶向一个盘子中的纸巾喷水，把纸巾打湿\n\n⑦观察两个盘子中菜籽的发芽情况实验结果：喷水盘子中的菜籽陆续发芽了，而加有食醋的盘子中的菜籽却基本没发芽。","explanation":"98、本题考查生物实验。\n\n本题为实验步骤排序题，根据对选项的分析，第一步可能为②、③、④、⑤中任意一个。按顺序进行分析，首先排除②，该步骤提到“同样将第二个盘子”进行处理，则在之前必有对第一个盘子的处理，因此可直接观察其他步骤，是否有对第一个盘子进行处理的描述，⑥有相关描述，因此⑥应在②之前。\n\n符合要求的仅有B、D 项，只需分析③、⑤的先后即可解决。\n\n经分析应该先铺纸巾才能将菜籽铺到纸巾上，因此③在⑤之前，只有B 项满足要求。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2024/2024-03-30/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[17],"answerPages":[46,47]},"idx":97,"pid":"p3f16ff5043","sourceYears":[2024]},{"qid":"sy-c-20240330-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"本实验的结果不能被用来说明（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[17],"answer":[47]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20240330-099-题目-p17-192-251.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-03-30-m98-材料-p16-622-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2024-03-30-m98-材料-p17-51-154.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"菜籽发芽的条件"},{"k":"B","t":"醋对种子发芽速度的影响"},{"k":"C","t":"如何在居家环境下种植绿植"},{"k":"D","t":"不同酸碱度环境对种子发芽的影响"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20240330-099-解析-p47-155-367.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"本实验的结果不能被用来说明（ ）。","options":[{"k":"A","t":"菜籽发芽的条件"},{"k":"B","t":"醋对种子发芽速度的影响"},{"k":"C","t":"如何在居家环境下种植绿植"},{"k":"D","t":"不同酸碱度环境对种子发芽的影响"}],"material":"（三）实验材料：2个盘子、2个玻璃碗、1个装满水的喷雾瓶，餐巾纸、食醋、菜籽若干。\n\n实验步骤：\n\n①把玻璃碗分别扣在两个盘子上\n\n②同样将第二个盘子的纸巾喷水打湿，并在纸巾上加入食醋\n\n③在两个盘子上分别铺上餐巾纸\n\n④把两个盘子移到温暖有光照的地方\n\n⑤把菜籽均匀地撒在两个盘子的纸巾上\n\n⑥用喷雾瓶向一个盘子中的纸巾喷水，把纸巾打湿\n\n⑦观察两个盘子中菜籽的发芽情况实验结果：喷水盘子中的菜籽陆续发芽了，而加有食醋的盘子中的菜籽却基本没发芽。","explanation":"99、(二)本题考查生物实验。\n\n根据材料分析，本题实验步骤为③⑥②⑤①④⑦。\n\nA、B、D 项正确，C 项错误。题干中种子具备了光照、水分的条件，两盘种子分别作为对照组和实验组，差异条件为醋，观察的实验现象为种子的发芽率。该实验目的为研究醋对种子发芽的影响，因为醋呈酸性，也可以认为实验目的是研究酸碱性对种子发芽的影响。因此实验中影响种子发芽的条件为光照、水分和醋（酸碱性）。\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2024/2024-03-30/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[17],"answerPages":[47]},"idx":98,"pid":"p3f16ff5043","sourceYears":[2024]},{"qid":"sy-c-20240330-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"本实验有助于解释以下哪项？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[17],"answer":[47]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20240330-100-题目-p17-247-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-03-30-m98-材料-p16-622-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2024-03-30-m98-材料-p17-51-154.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"盐碱地农作物歉收的原因"},{"k":"B","t":"酸雨环境不利于农业生产的原因"},{"k":"C","t":"空气不流通不利于农业生产的原因"},{"k":"D","t":"温带农作物产量高于高寒地区的原因更多网课资料加v：hu20200828"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20240330-100-解析-p47-363-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"本实验有助于解释以下哪项？（ ）","options":[{"k":"A","t":"盐碱地农作物歉收的原因"},{"k":"B","t":"酸雨环境不利于农业生产的原因"},{"k":"C","t":"空气不流通不利于农业生产的原因"},{"k":"D","t":"温带农作物产量高于高寒地区的原因更多网课资料加v：hu20200828"}],"material":"（三）实验材料：2个盘子、2个玻璃碗、1个装满水的喷雾瓶，餐巾纸、食醋、菜籽若干。\n\n实验步骤：\n\n①把玻璃碗分别扣在两个盘子上\n\n②同样将第二个盘子的纸巾喷水打湿，并在纸巾上加入食醋\n\n③在两个盘子上分别铺上餐巾纸\n\n④把两个盘子移到温暖有光照的地方\n\n⑤把菜籽均匀地撒在两个盘子的纸巾上\n\n⑥用喷雾瓶向一个盘子中的纸巾喷水，把纸巾打湿\n\n⑦观察两个盘子中菜籽的发芽情况实验结果：喷水盘子中的菜籽陆续发芽了，而加有食醋的盘子中的菜籽却基本没发芽。","explanation":"100、本题考查生物实验。\n\nA、C、D 项错误，B 项正确。该实验目的为研究醋对种子发芽的影响，因为醋呈酸性，也可以认为实验目的是研究酸碱性对种子发芽的影响。因此实验中影响种子发芽的条件为光照、水分和醋（酸性条件）。选项中与酸性条件相关的仅有酸雨环境，其他选项条件与题目实验条件无关。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2024/2024-03-30/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[17],"answerPages":[47]},"idx":99,"pid":"p3f16ff5043","sourceYears":[2024]},{"qid":"sy-c-20241102-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（单选题）实验步骤是被打乱的，正确的实验步骤应为：","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22],"answer":[28]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20241102-096-题目-p22-152-224.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p21-405-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p22-51-152.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"（1）（2）（3）（5）（4）"},{"k":"B","t":"（1）（2）（5）（4）（3）"},{"k":"C","t":"（2）（1）（4）（5）（3）"},{"k":"D","t":"（2）（1）（5）（3）（4）"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20241102-096-解析-p28-589-705.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）实验步骤是被打乱的，正确的实验步骤应为：","options":[{"k":"A","t":"（1）（2）（3）（5）（4）"},{"k":"B","t":"（1）（2）（5）（4）（3）"},{"k":"C","t":"（2）（1）（4）（5）（3）"},{"k":"D","t":"（2）（1）（5）（3）（4）"}],"material":"2.实验设计行为激励实验被试：100名四岁学龄前儿童材料：（1）四种不同形状的儿童积木（正方形、圆形、梯形、三角形）（2）具有正方形、圆形、梯形和三角形轮廓的木板（3）秒表或计时器（4）贴纸实验步骤：（1）将所有儿童随机分为A、B两组，A组被告知将得到表扬作为完成任务的奖励；B组被告知将得到奖品（贴纸）作为完成任务的奖励。\n\n（2）告知所有儿童，任务为快速、准确地将不同形状的积木放在木板上与其匹配的轮廓内。\n\n（3）实验完成后，计算每组的平均用时。\n\n（4）计算平均用时之间的差异是否具有统计学意义。\n\n（5）记录每个参与者的测试结果。\n\n注意事项：（1）实验结束前，A组和B组均不能知道另一组获得的奖励内容。\n\n（2）两组应在同一地点进行测试，测试环境要尽量避免分散儿童注意力。","explanation":"96\n\n本题考查心理学实验。\n\n步骤（1）、（2）没有明显的逻辑顺序，观察步骤（3）、（4）、（5），步骤（5）为记录每个参与者的测试结果，而步骤（3）为计算每组的平均用时，只有先记录每个参与者的测试结果才能计算平均用时，因此步骤（5）在步骤（3）之前；而步骤（4）为计算平均用时之间的差异，因此步骤（4）应在步骤（3）之后，即实验步骤排序应为（5）（3）（4），只有D项符合。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2024/2024-11-02/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22],"answerPages":[28]},"idx":95,"pid":"p4dd91af038","sourceYears":[2024]},{"qid":"sy-c-20241102-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（单选题）如果两组之间的结果存在具有统计学意义的差异，则说明：","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22],"answer":[28,29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20241102-097-题目-p22-220-334.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p21-405-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p22-51-152.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"对儿童的口头表扬和实物激励具有不同的效果"},{"k":"B","t":"外部激励对儿童行为的影响具有显著的个体差异"},{"k":"C","t":"儿童完成任务的专注程度可能会受到外部激励的影响"},{"k":"D","t":"同一年龄的不同儿童在动手能力上可能存在显著差异"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20241102-097-解析-p28-700-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20241102-097-解析-p29-51-111.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）如果两组之间的结果存在具有统计学意义的差异，则说明：","options":[{"k":"A","t":"对儿童的口头表扬和实物激励具有不同的效果"},{"k":"B","t":"外部激励对儿童行为的影响具有显著的个体差异"},{"k":"C","t":"儿童完成任务的专注程度可能会受到外部激励的影响"},{"k":"D","t":"同一年龄的不同儿童在动手能力上可能存在显著差异"}],"material":"2.实验设计行为激励实验被试：100名四岁学龄前儿童材料：（1）四种不同形状的儿童积木（正方形、圆形、梯形、三角形）（2）具有正方形、圆形、梯形和三角形轮廓的木板（3）秒表或计时器（4）贴纸实验步骤：（1）将所有儿童随机分为A、B两组，A组被告知将得到表扬作为完成任务的奖励；B组被告知将得到奖品（贴纸）作为完成任务的奖励。\n\n（2）告知所有儿童，任务为快速、准确地将不同形状的积木放在木板上与其匹配的轮廓内。\n\n（3）实验完成后，计算每组的平均用时。\n\n（4）计算平均用时之间的差异是否具有统计学意义。\n\n（5）记录每个参与者的测试结果。\n\n注意事项：（1）实验结束前，A组和B组均不能知道另一组获得的奖励内容。\n\n（2）两组应在同一地点进行测试，测试环境要尽量避免分散儿童注意力。","explanation":"本题考查心理学实验。\n\n97\n\nA项正确，如果两组之间的结果存在具有统计学意义的差异，说明上述实验的干预措施（口头表扬和贴纸奖励）是有效的，也就是口头表扬和贴纸奖励对儿童有不同的激励效果，则可以说明对儿童的口头表扬和实物激励具有不同的效果。\n\nB项错误，如果两组之间的结果存在具有统计学意义的差异，只能说明两组数据的平均值存在显著的差异，而由于个体数据已经被“平均”，因此无法其中的个体是否存在差异。\n\nC项错误，上述实验中仅记录的儿童完成任务的时间，并未观察儿童完成实验过程的专注程度，选项偷换概念。\n\nD项错误，上述实验并未测试儿童的动手能力，且选项未提及实验的主题“激励”。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2024/2024-11-02/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22],"answerPages":[28,29]},"idx":96,"pid":"p4dd91af038","sourceYears":[2024]},{"qid":"sy-c-20241102-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（单选题）以下哪项措施最能够保证注意事项（1）的落实？","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22],"answer":[29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20241102-098-题目-p22-330-684.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p21-405-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p22-51-152.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"让所有儿童在同一空间内等待测试的依次进行"},{"k":"B","t":"让两组儿童在分组后相互隔离直至整个测试结束"},{"k":"C","t":"告诉B组儿童他们将在整个测试结束之后才能得到贴纸"},{"k":"D","t":"在测试结束后向A组中完成任务的儿童也发放贴纸作为奖励实验材料：透明塑料瓶，透明塑料管，彩色泡沫塑料，封口材料实验步骤：（1）把塑料瓶装满水（2）封住塑料管两端做成浮标（3）用一只手拿住瓶口，另一只手将浮标按在水中（4）把瓶子举到高处，同时松开双手，让瓶子自由下落（5）在塑料管中塞入一些彩色泡沫塑料实验结果：在瓶子下落过程中，浮标一直留在水里，直到瓶子落地后，才会被瓶子里冲出来的水带到瓶外。"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20241102-098-解析-p29-107-282.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）以下哪项措施最能够保证注意事项（1）的落实？","options":[{"k":"A","t":"让所有儿童在同一空间内等待测试的依次进行"},{"k":"B","t":"让两组儿童在分组后相互隔离直至整个测试结束"},{"k":"C","t":"告诉B组儿童他们将在整个测试结束之后才能得到贴纸"},{"k":"D","t":"在测试结束后向A组中完成任务的儿童也发放贴纸作为奖励实验材料：透明塑料瓶，透明塑料管，彩色泡沫塑料，封口材料实验步骤：（1）把塑料瓶装满水（2）封住塑料管两端做成浮标（3）用一只手拿住瓶口，另一只手将浮标按在水中（4）把瓶子举到高处，同时松开双手，让瓶子自由下落（5）在塑料管中塞入一些彩色泡沫塑料实验结果：在瓶子下落过程中，浮标一直留在水里，直到瓶子落地后，才会被瓶子里冲出来的水带到瓶外。"}],"material":"2.实验设计行为激励实验被试：100名四岁学龄前儿童材料：（1）四种不同形状的儿童积木（正方形、圆形、梯形、三角形）（2）具有正方形、圆形、梯形和三角形轮廓的木板（3）秒表或计时器（4）贴纸实验步骤：（1）将所有儿童随机分为A、B两组，A组被告知将得到表扬作为完成任务的奖励；B组被告知将得到奖品（贴纸）作为完成任务的奖励。\n\n（2）告知所有儿童，任务为快速、准确地将不同形状的积木放在木板上与其匹配的轮廓内。\n\n（3）实验完成后，计算每组的平均用时。\n\n（4）计算平均用时之间的差异是否具有统计学意义。\n\n（5）记录每个参与者的测试结果。\n\n注意事项：（1）实验结束前，A组和B组均不能知道另一组获得的奖励内容。\n\n（2）两组应在同一地点进行测试，测试环境要尽量避免分散儿童注意力。","explanation":"98\n\n本题考查心理学实验。\n\nA项错误，让所有儿童在同一空间内等待测试的依次进行，则儿童们在等待测试期间相互聊天会泄露奖励内容，导致实验失败。\n\nB项正确，若要保证实验结束前，A组和B组均不能知道另一组获得的奖励内容，则必须在在分组后就切断两组儿童之间的信息交流，将两组儿童相互隔离直至整个测试结束，否则儿童之间相互聊天可能会导致两组儿童知道对方的奖励内容。\n\nC、D项错误，这两种措施虽然能在形式上隐藏两组儿童的实验奖励差异，但仍无法阻止两组儿童之间的信息交流。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2024/2024-11-02/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22],"answerPages":[29]},"idx":97,"pid":"p4dd91af038","sourceYears":[2024]},{"qid":"sy-c-20241102-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（单选题）上述实验步骤的顺序是错乱的，以下哪项是最为合理的实验步骤？","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22],"answer":[29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20241102-099-题目-p22-680-752.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p21-405-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p22-51-152.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"（1）（5）（2）（3）（4）"},{"k":"B","t":"（1）（5）（3）（2）（4）"},{"k":"C","t":"（2）（1）（3）（5）（4）"},{"k":"D","t":"（5）（2）（3）（1）（4）"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20241102-099-解析-p29-278-396.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）上述实验步骤的顺序是错乱的，以下哪项是最为合理的实验步骤？","options":[{"k":"A","t":"（1）（5）（2）（3）（4）"},{"k":"B","t":"（1）（5）（3）（2）（4）"},{"k":"C","t":"（2）（1）（3）（5）（4）"},{"k":"D","t":"（5）（2）（3）（1）（4）"}],"material":"2.实验设计行为激励实验被试：100名四岁学龄前儿童材料：（1）四种不同形状的儿童积木（正方形、圆形、梯形、三角形）（2）具有正方形、圆形、梯形和三角形轮廓的木板（3）秒表或计时器（4）贴纸实验步骤：（1）将所有儿童随机分为A、B两组，A组被告知将得到表扬作为完成任务的奖励；B组被告知将得到奖品（贴纸）作为完成任务的奖励。\n\n（2）告知所有儿童，任务为快速、准确地将不同形状的积木放在木板上与其匹配的轮廓内。\n\n（3）实验完成后，计算每组的平均用时。\n\n（4）计算平均用时之间的差异是否具有统计学意义。\n\n（5）记录每个参与者的测试结果。\n\n注意事项：（1）实验结束前，A组和B组均不能知道另一组获得的奖励内容。\n\n（2）两组应在同一地点进行测试，测试环境要尽量避免分散儿童注意力。","explanation":"本题考查物理实验。\n\n99观察4个选项的第一步，发现步骤（2）、（5）中都出现了塑料管，步骤（5）是在塑料管中塞入彩色泡沫塑料，而步骤（2）是封住塑料管两端，因此步骤（5）在步骤（2）之前，排除C项；继续观察，发现（3）中出现了浮标和水，而浮标是步骤（2）中塑料管做成的，水是在步骤（1）中装入塑料瓶的，故步骤（1）和（2）都应在步骤（3）之前，排除B、D项，只有A项符合。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2024/2024-11-02/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22],"answerPages":[29]},"idx":98,"pid":"p4dd91af038","sourceYears":[2024]},{"qid":"sy-c-20241102-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（单选题） 本实验的目的可能是为了认识：","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22,23],"answer":[29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20241102-100-题目-p22-748-813.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20241102-100-题目-p23-51-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p21-405-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2024-11-02-m96-材料-p22-51-152.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"水的浮力大小"},{"k":"B","t":"物体在水中的运动"},{"k":"C","t":"水在失重状态下的浮力"},{"k":"D","t":"自由落体时物体的加速度"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20241102-100-解析-p29-392-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题） 本实验的目的可能是为了认识：","options":[{"k":"A","t":"水的浮力大小"},{"k":"B","t":"物体在水中的运动"},{"k":"C","t":"水在失重状态下的浮力"},{"k":"D","t":"自由落体时物体的加速度"}],"material":"2.实验设计行为激励实验被试：100名四岁学龄前儿童材料：（1）四种不同形状的儿童积木（正方形、圆形、梯形、三角形）（2）具有正方形、圆形、梯形和三角形轮廓的木板（3）秒表或计时器（4）贴纸实验步骤：（1）将所有儿童随机分为A、B两组，A组被告知将得到表扬作为完成任务的奖励；B组被告知将得到奖品（贴纸）作为完成任务的奖励。\n\n（2）告知所有儿童，任务为快速、准确地将不同形状的积木放在木板上与其匹配的轮廓内。\n\n（3）实验完成后，计算每组的平均用时。\n\n（4）计算平均用时之间的差异是否具有统计学意义。\n\n（5）记录每个参与者的测试结果。\n\n注意事项：（1）实验结束前，A组和B组均不能知道另一组获得的奖励内容。\n\n（2）两组应在同一地点进行测试，测试环境要尽量避免分散儿童注意力。","explanation":"100\n\n本题考查物理实验。\n\n上述实验在瓶子自由下落前，由于浮标受到浮力，需要用手按住才能使浮标不被浮力带出塑料瓶，而在瓶子自由下落的过程中，浮标始终保持在水中，说明在瓶子自由下落过程中并未收到水的浮力，进一步分析可知，瓶子在自由下落时，水处于失重状态，根据上述实验可以得出的结论是：水在完全失重状态下对水中的物体是没有浮力的，因此上述实验的目的是为了认识水在失重状态下的浮力。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2024/2024-11-02/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22,23],"answerPages":[29]},"idx":99,"pid":"p4dd91af038","sourceYears":[2024]},{"qid":"sy-c-20230507-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"这项实验意图证明（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[29,30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-096-题目-p23-350-448.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-05-07-m96-材料-p23-210-350.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"人类对深度的知觉是天生的"},{"k":"B","t":"幼年人类对母亲有天生的亲近感"},{"k":"C","t":"婴儿的视觉认知与成年人的存在差异"},{"k":"D","t":"人类生来就能认识到特定的颜色代表危险"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-096-解析-p29-522-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20230507-096-解析-p30-51-339.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"这项实验意图证明（ ）。","options":[{"k":"A","t":"人类对深度的知觉是天生的"},{"k":"B","t":"幼年人类对母亲有天生的亲近感"},{"k":"C","t":"婴儿的视觉认知与成年人的存在差异"},{"k":"D","t":"人类生来就能认识到特定的颜色代表危险"}],"material":"（六）在“视崖实验”中，研究人员首先设计并制作了一个视崖装置，装置为一张1.2 米的桌子，桌面是一块透明的厚玻璃。桌面的一半在玻璃下方贴有红白相间的格子纸，桌面的另一半是透明的，但在地上贴有同样图案的格子纸，从桌面上看，图案好像直接落到了地面上，从视觉上像一个有深度的悬崖。\n\n研究人员招募了36 个年龄在6 14 个月之间的婴儿，然后依次把婴儿放在桌子的中间，先让妈妈在看起来深的一侧呼唤孩子，然后再在看起来浅的一侧呼唤孩子，看婴儿会不会爬向妈妈。\n\n在实验中，有9 名婴儿拒绝离开中间。剩余的27 个婴儿当妈妈在浅的一侧呼唤他们时，都爬向了妈妈，当妈妈在深的一侧呼唤他们时，只有3 个婴儿极为犹豫地爬过了视崖，而剩余的孩子都拒绝爬过去，甚至有的因为够不到妈妈而大哭。","explanation":"备注：此题表述不够严谨，问的应为必跟何、赵在同一个半天做报告的人。\n\n96\n\n本题考查心理学实验。\n\nA项正确，实验中，绝大部分婴儿拒绝爬过“深渊”，但都能爬过“浅滩”。这说明婴儿已经意识到视崖深度的存在，即人类对深度的知觉是天生的;\n\nB项错误，实验中并未让其他人呼唤婴儿进行对比，无法得出该结论；\n\nC项错误，实验中并未设置成人组与婴儿组实验进行对比，无法得出该结论；\n\nD项错误，实验中，“深渊”与“浅滩”的颜色是相同的，无法得出该结论。\n\n淘宝：上岸大已只有玻璃深渊中间板浅滩\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[29,30]},"idx":95,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-c-20230507-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"以下哪项可以让实验结果更有说服力？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23,24],"answer":[30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-097-题目-p23-444-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20230507-097-题目-p24-51-386.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-05-07-m96-材料-p23-210-350.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"让婴儿的其他家庭成员在实验中呼唤婴儿"},{"k":"B","t":"增加年龄更大的幼儿作为对照组进行同一实验"},{"k":"C","t":"在无视崖效果的平面上重复此实验并进行对照"},{"k":"D","t":"调换深侧、浅侧的先后顺序重复此实验进行对照"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-097-解析-p30-334-496.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下哪项可以让实验结果更有说服力？（ ）","options":[{"k":"A","t":"让婴儿的其他家庭成员在实验中呼唤婴儿"},{"k":"B","t":"增加年龄更大的幼儿作为对照组进行同一实验"},{"k":"C","t":"在无视崖效果的平面上重复此实验并进行对照"},{"k":"D","t":"调换深侧、浅侧的先后顺序重复此实验进行对照"}],"material":"（六）在“视崖实验”中，研究人员首先设计并制作了一个视崖装置，装置为一张1.2 米的桌子，桌面是一块透明的厚玻璃。桌面的一半在玻璃下方贴有红白相间的格子纸，桌面的另一半是透明的，但在地上贴有同样图案的格子纸，从桌面上看，图案好像直接落到了地面上，从视觉上像一个有深度的悬崖。\n\n研究人员招募了36 个年龄在6 14 个月之间的婴儿，然后依次把婴儿放在桌子的中间，先让妈妈在看起来深的一侧呼唤孩子，然后再在看起来浅的一侧呼唤孩子，看婴儿会不会爬向妈妈。\n\n在实验中，有9 名婴儿拒绝离开中间。剩余的27 个婴儿当妈妈在浅的一侧呼唤他们时，都爬向了妈妈，当妈妈在深的一侧呼唤他们时，只有3 个婴儿极为犹豫地爬过了视崖，而剩余的孩子都拒绝爬过去，甚至有的因为够不到妈妈而大哭。","explanation":"97\n\n本题考查心理学实验。\n\nA项错误，实验研究的是婴儿对深度的知觉感知能力，而非对不同人的亲和力；\n\nB项错误，年龄更大的幼儿，可能在后天生活中逐渐提高对深度的知觉，不能增强实验结果的说服力;\n\nC项错误，本实验中两次呼唤本身就存在着平面和“深渊”的对照，再增加一次无视崖效果的平面实验对实验结果有一定的增强作用，但力度较弱;\n\nD项正确，调换深侧、浅侧的先后顺序重复实验，可以排除先后顺序对实验结果的影响。因为存在一种可能，母亲第一次呼唤婴儿时，婴儿由于某种原因，正犹豫或考虑是否要爬过去，而当母亲再次呼唤婴儿时，婴儿才决定爬过视崖。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23,24],"answerPages":[30]},"idx":96,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-c-20230507-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"以下除哪项外，均是上述实验的目的？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[24],"answer":[30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-098-题目-p24-382-480.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-05-07-m98-材料-p23-538-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2023-05-07-m98-材料-p24-51-382.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"观察植物细胞在光学显微镜下的基本结构"},{"k":"B","t":"认识植物细胞的代谢产物"},{"k":"C","t":"掌握临时装片的制作技术"},{"k":"D","t":"了解植物细胞的基本功能"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-098-解析-p30-491-667.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下除哪项外，均是上述实验的目的？（ ）","options":[{"k":"A","t":"观察植物细胞在光学显微镜下的基本结构"},{"k":"B","t":"认识植物细胞的代谢产物"},{"k":"C","t":"掌握临时装片的制作技术"},{"k":"D","t":"了解植物细胞的基本功能"}],"material":"（七）【材料与用品】洋葱、番茄、白菜心、菠菜、红辣椒、紫竹梅、万寿菊管状花瓣、柿子胚乳细胞永久封片、松树木材、橡皮树叶横切片、秋海棠叶柄、鸭跖草叶、马铃薯块茎、橘皮、花生。\n\n显微镜、尖头镊子、载玻片、盖玻片、滴瓶、培养皿、滴管、刀片、剪刀、解剖针、吸水纸、擦镜纸、纱布。\n\n蒸馏水、I-KI 溶液、稀硫酸溶液、酒精、甲基蓝液等。\n\n【内容与方法】1.植物细胞的基本结构（1）洋葱表皮装片的制作与观察\n\n①洋葱表皮装片的制作，取洋葱肉质鳞片，用刀片在鳞片内表皮划一个3～5mm²小格，用镊子撕一下薄膜状的内表皮，制成临时水封片（表面朝上），若水过多，用吸水纸清除。\n\n②洋葱表皮装片的观察，在显微镜下观察洋葱表皮细胞的形态和排列情况，留意观察细胞壁、细胞核、细胞质和液泡。\n\n（2）果肉离散细胞的观察。用尖头镊子挑取少许成熟的番茄果肉，制成临时装片，选一个离散细胞观察其基本结构，并比较与洋葱细胞的异同。\n\n2.质体的观察质体是植物细胞特有的结构，在不同的细胞中具有不同的类型。\n\n（1）白色体：用白菜或者油菜的白色菜心的幼叶的表皮制成装片观察，可见核周围的透明的颗粒状结构，即是白色体。\n\n（2）叶绿体：制成并观察菠菜叶装片，可见细胞中有许多绿色的椭圆形颗粒，即是叶绿体。\n\n（3）有色体：制成并观察红辣椒肉装片，可见颗粒状、条状、块状橙红色组织。\n\n3.原生质流动的观察制成并观察万寿菊管状花瓣装片中原生质流动的方向。\n\n4.植物细胞的胞间连丝和纹孔的观察（1）观察柿子胚乳的胞间连丝。\n\n（2）观察红辣椒果实表皮的初生纹孔场。\n\n（3）观察松木细胞壁上的具缘纹孔。\n\n5.后含物观察植物细胞的代谢物。\n\n（1）花青素是一种溶解在细胞液中的色素，制成并观察紫竹梅叶的装片可发现花青素均匀地分布在液泡中。\n\n（2）结晶体常存在于植物的表皮、皮层的细胞液中，制成并叶柄装片可见针晶或晶簇等结晶体。\n\n（3）制成并观察马铃薯块茎装片可见淀粉粒。\n\n（4）制成并观察橘皮装片可见油囊中的油滴。","explanation":"98\n\n本题考查生物实验。\n\nA项正确，实验中对洋葱表皮装片的制作与观察、果肉离散细胞的观察，以及对质体、植物细胞的胞间连丝和纹孔的观察，其目的均是观察植物细胞在光学显微镜下的基本结构。\n\nB项正确，后含物是原生质体新陈代谢的产物，是细胞中无生命的物质。后含物一部分是贮藏的营养物质，一部分是细胞不能再利用的废物。实验中紫竹梅叶中的花青素、马铃薯块茎中的淀粉、秋海棠叶柄中结晶体、橘皮中的油滴均属于后含物，对它们进行观察，是为了认识植物细胞的代谢产物。\n\nC项正确，进行上述实验时需要对植物细胞临时装片，上述实验步骤对装片过程特别是洋葱表皮装片进行了较为详细的阐述，因此掌握临时装片的制作技术也是上述实验的目的。\n\nD项错误，实验中仅对植物细胞结构进行的观察，但并未对各结构、部位的相关功能进行实验研究。\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[24],"answerPages":[30]},"idx":97,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-c-20230507-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"项的分类最为恰当的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[24],"answer":[30,31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-099-题目-p24-475-589.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-05-07-m98-材料-p23-538-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2023-05-07-m98-材料-p24-51-382.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"（1）油菜、红辣椒、紫竹梅、橘子；（2）油滴、白色体、有色体、花青素、结晶体"},{"k":"B","t":"（1）油菜、红辣椒、紫竹梅、橘子；（2）有色体、花青素；（3）白色体、油滴；（4）结晶体"},{"k":"C","t":"（1）油菜、白色体；（2）红辣椒、有色体；（3）紫竹梅、花青素；（4）橘子、油滴、结晶体"},{"k":"D","t":"（1）油菜、红辣椒、紫竹梅、橘子；（2）白色体、有色体；（3）油滴、花青素、结晶体"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-099-解析-p30-662-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20230507-099-解析-p31-51-183.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"根据以上实验，关于“油菜、红辣椒、油滴、白色体、紫竹梅、橘子、花青素、有色体、结晶体”9 个词项的分类最为恰当的是（ ）。","options":[{"k":"A","t":"（1）油菜、红辣椒、紫竹梅、橘子；（2）油滴、白色体、有色体、花青素、结晶体"},{"k":"B","t":"（1）油菜、红辣椒、紫竹梅、橘子；（2）有色体、花青素；（3）白色体、油滴；（4）结晶体"},{"k":"C","t":"（1）油菜、白色体；（2）红辣椒、有色体；（3）紫竹梅、花青素；（4）橘子、油滴、结晶体"},{"k":"D","t":"（1）油菜、红辣椒、紫竹梅、橘子；（2）白色体、有色体；（3）油滴、花青素、结晶体"}],"material":"（七）【材料与用品】洋葱、番茄、白菜心、菠菜、红辣椒、紫竹梅、万寿菊管状花瓣、柿子胚乳细胞永久封片、松树木材、橡皮树叶横切片、秋海棠叶柄、鸭跖草叶、马铃薯块茎、橘皮、花生。\n\n显微镜、尖头镊子、载玻片、盖玻片、滴瓶、培养皿、滴管、刀片、剪刀、解剖针、吸水纸、擦镜纸、纱布。\n\n蒸馏水、I-KI 溶液、稀硫酸溶液、酒精、甲基蓝液等。\n\n【内容与方法】1.植物细胞的基本结构（1）洋葱表皮装片的制作与观察\n\n①洋葱表皮装片的制作，取洋葱肉质鳞片，用刀片在鳞片内表皮划一个3～5mm²小格，用镊子撕一下薄膜状的内表皮，制成临时水封片（表面朝上），若水过多，用吸水纸清除。\n\n②洋葱表皮装片的观察，在显微镜下观察洋葱表皮细胞的形态和排列情况，留意观察细胞壁、细胞核、细胞质和液泡。\n\n（2）果肉离散细胞的观察。用尖头镊子挑取少许成熟的番茄果肉，制成临时装片，选一个离散细胞观察其基本结构，并比较与洋葱细胞的异同。\n\n2.质体的观察质体是植物细胞特有的结构，在不同的细胞中具有不同的类型。\n\n（1）白色体：用白菜或者油菜的白色菜心的幼叶的表皮制成装片观察，可见核周围的透明的颗粒状结构，即是白色体。\n\n（2）叶绿体：制成并观察菠菜叶装片，可见细胞中有许多绿色的椭圆形颗粒，即是叶绿体。\n\n（3）有色体：制成并观察红辣椒肉装片，可见颗粒状、条状、块状橙红色组织。\n\n3.原生质流动的观察制成并观察万寿菊管状花瓣装片中原生质流动的方向。\n\n4.植物细胞的胞间连丝和纹孔的观察（1）观察柿子胚乳的胞间连丝。\n\n（2）观察红辣椒果实表皮的初生纹孔场。\n\n（3）观察松木细胞壁上的具缘纹孔。\n\n5.后含物观察植物细胞的代谢物。\n\n（1）花青素是一种溶解在细胞液中的色素，制成并观察紫竹梅叶的装片可发现花青素均匀地分布在液泡中。\n\n（2）结晶体常存在于植物的表皮、皮层的细胞液中，制成并叶柄装片可见针晶或晶簇等结晶体。\n\n（3）制成并观察马铃薯块茎装片可见淀粉粒。\n\n（4）制成并观察橘皮装片可见油囊中的油滴。","explanation":"99\n\n本题考查生物实验。\n\n（1）油菜、红辣椒、紫竹梅、橘子属于完整的植物个体;（2）白色体和有色体属于质体，质体是植物细胞特有的结构，不同的细胞中具有不同的类型。白色体多存在于植物体的幼嫩细胞或不见光的细胞中，有些植物的表皮细胞中也有，但个体小。有色体是含有胡萝卜素及叶黄素的质体，由于两种色素比例不同，可分别呈黄色、橙色或橙红色，主要存在于花、果实中，有时也见于植物的营养器官；\n\n（3）油滴、花青素、结晶体属于植物细胞中常见的代谢产物。其中花青素是一种常溶解在细胞液中的色素，能使植物的茎、叶、花和果实呈现红色、紫色和兰色等各种颜色；淀粉可为植物提供能量的主要来源；经晶体常存在于表皮、皮层、髓和韧皮部等处的薄壁细胞的细胞液中；橘皮的油滴主要成分为苎烯，是橘子等植物的代谢产物。\n\n故正确答案为 D。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[24],"answerPages":[30,31]},"idx":98,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-c-20230507-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"根据以上实验，可以推测以下哪项会影响植物的叶、花和果实呈现不同颜色？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[24],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230507-100-题目-p24-584-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-05-07-m98-材料-p23-538-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2023-05-07-m98-材料-p24-51-382.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"白色体"},{"k":"B","t":"结晶体"},{"k":"C","t":"花青素"},{"k":"D","t":"原生质"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230507-100-解析-p31-178-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"根据以上实验，可以推测以下哪项会影响植物的叶、花和果实呈现不同颜色？（ ）","options":[{"k":"A","t":"白色体"},{"k":"B","t":"结晶体"},{"k":"C","t":"花青素"},{"k":"D","t":"原生质"}],"material":"（七）【材料与用品】洋葱、番茄、白菜心、菠菜、红辣椒、紫竹梅、万寿菊管状花瓣、柿子胚乳细胞永久封片、松树木材、橡皮树叶横切片、秋海棠叶柄、鸭跖草叶、马铃薯块茎、橘皮、花生。\n\n显微镜、尖头镊子、载玻片、盖玻片、滴瓶、培养皿、滴管、刀片、剪刀、解剖针、吸水纸、擦镜纸、纱布。\n\n蒸馏水、I-KI 溶液、稀硫酸溶液、酒精、甲基蓝液等。\n\n【内容与方法】1.植物细胞的基本结构（1）洋葱表皮装片的制作与观察\n\n①洋葱表皮装片的制作，取洋葱肉质鳞片，用刀片在鳞片内表皮划一个3～5mm²小格，用镊子撕一下薄膜状的内表皮，制成临时水封片（表面朝上），若水过多，用吸水纸清除。\n\n②洋葱表皮装片的观察，在显微镜下观察洋葱表皮细胞的形态和排列情况，留意观察细胞壁、细胞核、细胞质和液泡。\n\n（2）果肉离散细胞的观察。用尖头镊子挑取少许成熟的番茄果肉，制成临时装片，选一个离散细胞观察其基本结构，并比较与洋葱细胞的异同。\n\n2.质体的观察质体是植物细胞特有的结构，在不同的细胞中具有不同的类型。\n\n（1）白色体：用白菜或者油菜的白色菜心的幼叶的表皮制成装片观察，可见核周围的透明的颗粒状结构，即是白色体。\n\n（2）叶绿体：制成并观察菠菜叶装片，可见细胞中有许多绿色的椭圆形颗粒，即是叶绿体。\n\n（3）有色体：制成并观察红辣椒肉装片，可见颗粒状、条状、块状橙红色组织。\n\n3.原生质流动的观察制成并观察万寿菊管状花瓣装片中原生质流动的方向。\n\n4.植物细胞的胞间连丝和纹孔的观察（1）观察柿子胚乳的胞间连丝。\n\n（2）观察红辣椒果实表皮的初生纹孔场。\n\n（3）观察松木细胞壁上的具缘纹孔。\n\n5.后含物观察植物细胞的代谢物。\n\n（1）花青素是一种溶解在细胞液中的色素，制成并观察紫竹梅叶的装片可发现花青素均匀地分布在液泡中。\n\n（2）结晶体常存在于植物的表皮、皮层的细胞液中，制成并叶柄装片可见针晶或晶簇等结晶体。\n\n（3）制成并观察马铃薯块茎装片可见淀粉粒。\n\n（4）制成并观察橘皮装片可见油囊中的油滴。","explanation":"100\n\n本题考查生物实验。\n\nA项错误，白色体质体的一种，不含色素。上述实验中，用白菜或者油菜的白色菜心观察白色体，说明白色体不含色素，不会使植物的叶、花和果实呈现不同颜色。\n\nB项错误，结晶体是植物细胞中常见的代谢产物，常存在于表皮、皮层、髓和韧皮部等处的薄壁细胞的细胞液中。上述实验中选择在秋海棠叶柄装片中观察结晶体，可以推测结晶体在叶、花和果中的含量不多，不会不会使植物的叶、花和果实呈现不同颜色。\n\nC项正确，紫竹梅叶片本身呈鲜明的紫色，紫竹梅叶片中观察到花青素均匀的分布在液泡中，而液泡占细胞面积约90%，所以叶片的颜色受液泡颜色的影响最大，据此可推测花青素会使会植物的叶、花和果实呈现不同颜色。\n\nD项错误，原生质是具有一定弹性和粘度的、半透明的、不均一的亲水胶体，胶体由分散相和连续相构成。\n\n根据上述实验可知原生质可以在细胞内流动，所以推测原生质是无色或半透明的，不会使植物的叶、花和果实呈现不同颜色。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2023/2023-05-07/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[24],"answerPages":[31]},"idx":99,"pid":"p45f7e1bcda","sourceYears":[2023]},{"qid":"sy-c-20230826-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"实验步骤（1）中最为合适的顺序是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[16],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230826-096-题目-p16-414-455.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-08-26-m96-材料-p15-612-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2023-08-26-m96-材料-p16-51-414.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"②④①⑥③⑤"},{"k":"B","t":"④②①⑤⑥③"},{"k":"C","t":"①③②⑤⑥④"},{"k":"D","t":"③⑤①⑥②④"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230826-096-解析-p31-72-167.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"实验步骤（1）中最为合适的顺序是（ ）。","options":[{"k":"A","t":"②④①⑥③⑤"},{"k":"B","t":"④②①⑤⑥③"},{"k":"C","t":"①③②⑤⑥④"},{"k":"D","t":"③⑤①⑥②④"}],"material":"（二）实验材料：（1）鲜黄瓜，鲜洋白菜，鲜西红柿。\n\n（2）锥形瓶（100mL），组织捣碎器，吸量管（10mL），漏斗。滤纸、微量滴定管（5mL），容量器（100mL，250mL）。\n\n（3）2%草酸溶液100mL，1%草酸溶液100mL，标准维生素C 溶液（1mg/mL）、0.1%的2，6-二氯酚靛酚溶液。实验步骤：（1）提取鲜果蔬滤液\n\n①称取20g 果蔬和20mL 草酸。\n\n②用四层纱布过滤，提取滤液。\n\n③用清水洗净整株蔬菜或整个新鲜水果。\n\n④合并滤液，滤液总体积定容至50mL。\n\n⑤用纱布或吸水纸吸干果蔬表面水分。\n\n⑥用钵体研磨。\n\n（2）标准液滴定吸取标准维生素C 溶液1mL 置于100ml 锥形瓶中，加1%草酸9mL，用微量滴定管以0.1%的2，6-二氯酚靛酚溶液滴定至淡红色，并保持15s 不褪色，即达终点。\n\n（3）样品滴定准确吸取滤液两份，每份10mL，分别放入2 个锥形瓶内，滴定方法同前。另外取1%草酸10mL 作空白滴定。（4）计算维生素C 含量（mg/100。样品） 式中， 为滴定样品所耗用2，6-二氯酚靛酚溶液的平均毫升数；VB 为滴定空白滴定所耗用2，6-二氯酚靛酚溶液的平均毫升数；C 为样品提取液的总毫升数；\n\nT 为1mL 的2，6-二氯酚靛酚溶液所能氧化维生素C 毫克数；D 为滴定时所取样品提取液的毫升数；W 为待测样品的重量（g）。\n\n实验原理：用2，6-二氯酚靛酚溶液滴定含有维生素C 的酸性溶液时，一旦溶液中的维生素C 已经全部被其氧化，则所滴溶液变成粉红色。","explanation":"96、参考答案：D\n\n解析：本题考查生物实验。\n\n实验步骤（1）的目的是提取鲜果蔬滤液，则在用钵体对果蔬研磨前必须将果蔬清洗干净并擦干表面水分。因此，步骤③⑤捆绑，且在步骤⑥之前，排除A、B、C 项。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2023/2023-08-26/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[16],"answerPages":[31]},"idx":95,"pid":"p02398bdfac","sourceYears":[2023]},{"qid":"sy-c-20230826-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"本实验的目的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[16],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230826-097-题目-p16-450-545.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-08-26-m96-材料-p15-612-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2023-08-26-m96-材料-p16-51-414.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"了解果蔬中维生素C 的含量"},{"k":"B","t":"掌握测定维生素C 的计算方法"},{"k":"C","t":"掌握维生素C 的测定原理和方法"},{"k":"D","t":"了解2，6-二氯酚靛酚溶液的用途"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230826-097-解析-p31-162-365.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"本实验的目的是（ ）。","options":[{"k":"A","t":"了解果蔬中维生素C 的含量"},{"k":"B","t":"掌握测定维生素C 的计算方法"},{"k":"C","t":"掌握维生素C 的测定原理和方法"},{"k":"D","t":"了解2，6-二氯酚靛酚溶液的用途"}],"material":"（二）实验材料：（1）鲜黄瓜，鲜洋白菜，鲜西红柿。\n\n（2）锥形瓶（100mL），组织捣碎器，吸量管（10mL），漏斗。滤纸、微量滴定管（5mL），容量器（100mL，250mL）。\n\n（3）2%草酸溶液100mL，1%草酸溶液100mL，标准维生素C 溶液（1mg/mL）、0.1%的2，6-二氯酚靛酚溶液。实验步骤：（1）提取鲜果蔬滤液\n\n①称取20g 果蔬和20mL 草酸。\n\n②用四层纱布过滤，提取滤液。\n\n③用清水洗净整株蔬菜或整个新鲜水果。\n\n④合并滤液，滤液总体积定容至50mL。\n\n⑤用纱布或吸水纸吸干果蔬表面水分。\n\n⑥用钵体研磨。\n\n（2）标准液滴定吸取标准维生素C 溶液1mL 置于100ml 锥形瓶中，加1%草酸9mL，用微量滴定管以0.1%的2，6-二氯酚靛酚溶液滴定至淡红色，并保持15s 不褪色，即达终点。\n\n（3）样品滴定准确吸取滤液两份，每份10mL，分别放入2 个锥形瓶内，滴定方法同前。另外取1%草酸10mL 作空白滴定。（4）计算维生素C 含量（mg/100。样品） 式中， 为滴定样品所耗用2，6-二氯酚靛酚溶液的平均毫升数；VB 为滴定空白滴定所耗用2，6-二氯酚靛酚溶液的平均毫升数；C 为样品提取液的总毫升数；\n\nT 为1mL 的2，6-二氯酚靛酚溶液所能氧化维生素C 毫克数；D 为滴定时所取样品提取液的毫升数；W 为待测样品的重量（g）。\n\n实验原理：用2，6-二氯酚靛酚溶液滴定含有维生素C 的酸性溶液时，一旦溶液中的维生素C 已经全部被其氧化，则所滴溶液变成粉红色。","explanation":"97、参考答案：C\n\n解析：本题考查生物实验。\n\nA、B 项错误，C 项正确，上述实验不仅可以得到维生素C 的含量，还解释了实验原理，且详细论述了定量计算维生素C 的方法，因此A、B 项均不全面。注：上述实验需要掌握维生素C 的测定原理和方法是：2，6-二氯酚靛酚在酸性溶液中呈粉红色，在中性或碱性溶液中呈蓝色，当用此染料滴定含有维生素C 的酸性溶液（草酸提供酸性环境）时，在维生素C 未全部氧化前，滴下染料立即被还原成无色，一旦溶液中的抗坏血酸全部被氧化时，则滴下的染料立即使溶液显示粉红色，此时为滴定终点，即表示溶液中的抗坏血酸刚刚被氧化完全，从滴定时2，6-二氯酚靛酚标准液的消耗量，可以计算出被检物质中维生素C 的含量。\n\nD 项错误，2，6-二氯酚靛酚溶液在本实验中充当指示剂的作用（根据颜色变化判断维生素C 是否全部氧化），了解其用途并非本实验的目的。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2023/2023-08-26/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[16],"answerPages":[31]},"idx":96,"pid":"p02398bdfac","sourceYears":[2023]},{"qid":"sy-c-20230826-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"对照实验","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"①对照性原则；②平行重复性原则；③单因子变量原则；④随机性原则。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[16],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230826-098-题目-p16-540-743.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-08-26-m96-材料-p15-612-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2023-08-26-m96-材料-p16-51-414.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"①②"},{"k":"B","t":"②③"},{"k":"C","t":"③④"},{"k":"D","t":"①③"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230826-098-解析-p31-360-707.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"在本实验中，主要体现了以下哪些实验原则？（ ）\n\n①对照性原则；②平行重复性原则；③单因子变量原则；④随机性原则。","options":[{"k":"A","t":"①②"},{"k":"B","t":"②③"},{"k":"C","t":"③④"},{"k":"D","t":"①③"}],"material":"（二）实验材料：（1）鲜黄瓜，鲜洋白菜，鲜西红柿。\n\n（2）锥形瓶（100mL），组织捣碎器，吸量管（10mL），漏斗。滤纸、微量滴定管（5mL），容量器（100mL，250mL）。\n\n（3）2%草酸溶液100mL，1%草酸溶液100mL，标准维生素C 溶液（1mg/mL）、0.1%的2，6-二氯酚靛酚溶液。实验步骤：（1）提取鲜果蔬滤液\n\n①称取20g 果蔬和20mL 草酸。\n\n②用四层纱布过滤，提取滤液。\n\n③用清水洗净整株蔬菜或整个新鲜水果。\n\n④合并滤液，滤液总体积定容至50mL。\n\n⑤用纱布或吸水纸吸干果蔬表面水分。\n\n⑥用钵体研磨。\n\n（2）标准液滴定吸取标准维生素C 溶液1mL 置于100ml 锥形瓶中，加1%草酸9mL，用微量滴定管以0.1%的2，6-二氯酚靛酚溶液滴定至淡红色，并保持15s 不褪色，即达终点。\n\n（3）样品滴定准确吸取滤液两份，每份10mL，分别放入2 个锥形瓶内，滴定方法同前。另外取1%草酸10mL 作空白滴定。（4）计算维生素C 含量（mg/100。样品） 式中， 为滴定样品所耗用2，6-二氯酚靛酚溶液的平均毫升数；VB 为滴定空白滴定所耗用2，6-二氯酚靛酚溶液的平均毫升数；C 为样品提取液的总毫升数；\n\nT 为1mL 的2，6-二氯酚靛酚溶液所能氧化维生素C 毫克数；D 为滴定时所取样品提取液的毫升数；W 为待测样品的重量（g）。\n\n实验原理：用2，6-二氯酚靛酚溶液滴定含有维生素C 的酸性溶液时，一旦溶液中的维生素C 已经全部被其氧化，则所滴溶液变成粉红色。","explanation":"98、参考答案：D\n\n解析：本题考查生物实验。\n\n①正确，对照性原则是指通过设置对照实验，既可排除无关变量的影响，又可增加实验结果的可信度和说服力。常用的对照类型有空白对照、自身对照、相互对照、条件对照、配对对照、标准对照、阳性对照、阴性对照、安慰剂对照等类型。上述实验步骤（3）样品滴定过程中，另外取1%草酸10mL 作空白滴定就属于空白对照。\n\n②错误，平行重复原则是指在实验设计中为了避免实验结果的偶然性，必须对所做实验在同样条件下进行足够次数的重复，不能只进行1-2 次便得出结论。也就是说，任何实验都必须有足够的实验次数才能判断结果的可靠性。上述实验未体现平行重复原则。\n\n③正确，单因子变量原则即单一变量原则，是指其他因素（无关变量）不变，只改变其中一个因素（要研究的因素——实验变量，即自变量），然后观察这个实验变量对实验结果的影响。上述实验步骤（2）为标准液滴定，步骤（3）样品滴定，通过改变这一变量，得出了不同的实验结果（消耗的2，6-二氯酚靛酚溶液量不同），从而根据公式计算出样品液中的维生素C 含量。\n\n④错误，随机性原则是指在选取样本时，应确保总体中任何一个个体都有同等的机会被抽取进入样本；\n\n在分配样本时，应确保样本中任何一个个体都有同等的机会被分入任何一个组中去。通过随机化，一是尽量使抽取的样本能够代表总体，减少抽样误差；二是使各组样本的条件尽量一致，消除或减少组间人为的误差，从而使处理因素产生的效应更加客观，便于得出正确的实验结果。上述实验并未体现随机性原则。\n\n综上所述，本实验主要体现了①对照性原则和③单因子变量原则。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2023/2023-08-26/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[16],"answerPages":[31]},"idx":97,"pid":"p02398bdfac","sourceYears":[2023]},{"qid":"sy-c-20230826-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"该实验最可能需要模拟出一个什么样的情境？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[16,17],"answer":[31,32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230826-099-题目-p16-738-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20230826-099-题目-p17-51-113.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-08-26-m99-材料-p16-594-738.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":99,"options":[{"k":"A","t":"被试的选择不受背景知识的影响"},{"k":"B","t":"被试的选择不受个人兴趣的影响"},{"k":"C","t":"被试的选择不受判断结果的影响"},{"k":"D","t":"被试的选择不受计算能力的影响"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230826-099-解析-p31-702-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20230826-099-解析-p32-51-185.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"该实验最可能需要模拟出一个什么样的情境？（ ）","options":[{"k":"A","t":"被试的选择不受背景知识的影响"},{"k":"B","t":"被试的选择不受个人兴趣的影响"},{"k":"C","t":"被试的选择不受判断结果的影响"},{"k":"D","t":"被试的选择不受计算能力的影响"}],"material":"（三）在某一实验中，研究人员要求被试对某一类学生参与某个社团组织的百分比（社团总人数为100）进行预估，因为分母为固定值100，所以实际上要求被试对分子的数值进行预估。\n\n首先，要求两组被试随机选择一个在0 到100 之间的数字；紧接着，研究人员告诉两组被试他们所选择的数字比实际值是大还是小；然后，要求被试对随机选择的数字进行一次调整来估计分子值。\n\n通过这一实验，研究人员发现，两组初始选择的数字对后面的估计会有显著的影响。比如，两组分别选定10 和65 作为开始数字，最终两组对分子值的平均估计分别为25 和45。由此可见，尽管被试对随机确定的数字有所调整，但他们还是将分子值的估计锚定在这一数字的一定范围内。","explanation":"99、参考答案：A\n\n解析：本题考查心理学实验。\n\n上述实验过程中，初始选定的数字与调整后的数字之间没有任何联系，但是人们往往不能忽略初始选定的数字的影响，在进行数值调整时往往将分子值的估计锚定在初始数字的一定范围内，这就是心理学上的锚定效应。但进行这一实验时，被试人员对某一类学生参与某个社团组织的百分比（即背景知识）是不清楚的，倘若被试人员清楚的知道某一类学生参与某个社团组织的百分比，则无论初始数字是多少，调整后的数字都是实际值，不再受到锚定效应的影响。因此，实验最可能需要模拟出的情境是被试的选择不受背景知识的影响。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2023/2023-08-26/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[16,17],"answerPages":[31,32]},"idx":98,"pid":"p02398bdfac","sourceYears":[2023]},{"qid":"sy-c-20230826-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"由材料第三段可以推导出，实际的分子数值（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[17],"answer":[32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20230826-100-题目-p17-108-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2023-08-26-m99-材料-p16-594-738.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":99,"options":[{"k":"A","t":"在10~25 之间"},{"k":"B","t":"在25~45 之间"},{"k":"C","t":".在45~65 之间"},{"k":"D","t":"在11~64 之间"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20230826-100-解析-p32-180-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"由材料第三段可以推导出，实际的分子数值（ ）。","options":[{"k":"A","t":"在10~25 之间"},{"k":"B","t":"在25~45 之间"},{"k":"C","t":".在45~65 之间"},{"k":"D","t":"在11~64 之间"}],"material":"（三）在某一实验中，研究人员要求被试对某一类学生参与某个社团组织的百分比（社团总人数为100）进行预估，因为分母为固定值100，所以实际上要求被试对分子的数值进行预估。\n\n首先，要求两组被试随机选择一个在0 到100 之间的数字；紧接着，研究人员告诉两组被试他们所选择的数字比实际值是大还是小；然后，要求被试对随机选择的数字进行一次调整来估计分子值。\n\n通过这一实验，研究人员发现，两组初始选择的数字对后面的估计会有显著的影响。比如，两组分别选定10 和65 作为开始数字，最终两组对分子值的平均估计分别为25 和45。由此可见，尽管被试对随机确定的数字有所调整，但他们还是将分子值的估计锚定在这一数字的一定范围内。","explanation":"100、参考答案：D\n\n解析：本题考查心理学实验。\n\n由材料第二段可知，实际的分子数值在11~64 之间；材料第三段，实验人员虽然对初始选择的数字作出了调整，但材料只讲述了调整后的数值受到初始数字的影响，并未对调整后的数字与实际值进行比较，也就无法进一步缩小实际的分子数值范围，且调整后的数值仅仅是两组估计值的平均数，并不能作为判断实际值的依据。因此，实际的分子数值范围仍为11~64 之间。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2023/2023-08-26/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[17],"answerPages":[32]},"idx":99,"pid":"p02398bdfac","sourceYears":[2023]},{"qid":"sy-c-20220521-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"关于实验步骤下列正确的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22],"answer":[28,29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-096-题目-p22-382-480.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-05-21-m96-材料-p21-475-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-05-21-m96-材料-p22-51-382.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"（3）（2）（5）（4）（1）"},{"k":"B","t":"（3）（4）（2）（5）（1）"},{"k":"C","t":"（5）（2）（1）（3）（4）"},{"k":"D","t":"（5）（3）（2）（1）（4）"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-096-解析-p28-646-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20220521-096-解析-p29-51-152.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于实验步骤下列正确的是（ ）。","options":[{"k":"A","t":"（3）（2）（5）（4）（1）"},{"k":"B","t":"（3）（4）（2）（5）（1）"},{"k":"C","t":"（5）（2）（1）（3）（4）"},{"k":"D","t":"（5）（3）（2）（1）（4）"}],"material":"（五）实验一实验器材：显微镜、载玻片、盖玻片、显微镜、滤纸、棉花纤维等实验步骤：（1）若所采样本中动物数量较少，可以用筛绢过滤浓缩或低速离心浓缩再观察（2）用滤纸把盖玻片多余的水吸走，先用低倍镜观察，再用高倍镜观察（3）将棉纤维放在载玻片上固定生物的运动状态（4）根据动物的形状特征及运动形态，先区别观察动物所属门类，再利用检索表进行检索（5）用吸管吸取水样，滴在载玻片上相关材料：原生动物：原生动物是一类由单细胞构成的微小动物，共有30000 余种，有不少种类生活在淡水中，营浮游生活。\n\n轮虫：多细胞动物，个体微小，身体一般分为头、躯干和尾3 部分。头部具有1～2 圈纤毛组成的轮盘（头冠），躯干常有兜甲，有咀嚼器，尾部末端常有1 对趾。\n\n枝角类：属节肢动物门、甲壳纲、鲤足亚纲、枝角目。通常称水蚤，俗称红虫。体长0.3～3mm，体短而左右侧扁，分节不明显，体被有两瓣透明的介壳，大多数种类的头部有显著的黑色复眼，第二触角发达呈枝角状，胸肢4～6 对，体末端有一爪状尾叉。\n\n桡足类：属节肢动物门、甲壳纲、桡足亚纲。身体纵长，分节明显，头胸部具附肢，腹部无附肢，末端有1 对尾叉，雄性个体头部第一触角左或右、或左右都变形为执握肢（器），雌性腹部两侧或腹面常附有卵囊。\n\n淡水浮游桡足类分为3 个目。\n\n枝角亚目分科检索表1.躯干部与胸肢全为壳瓣所包被....................................21.躯干部与胸肢均裸露与壳瓣之外.........................大眼溞科2.胸肢6 对，同形，均呈叶片状..........................仙达溞总科32.胸肢5～6 对，前两对呈执握状，其余呈叶片状...........盘肠溞总科43.第二触角不论性别，均为双肢型，具游泳刚毛多根..........仙达溞科3.第二触角雌体单肢型，有游泳刚毛3 根；雄体双肢型，共有游泳刚毛5 根（我国尚未发现）...........................................单肢溞科4.第二触角内外肢均为3 节。肠管盘曲，其后部大多有一个盲囊....盘肠溞科4.第二触角外肢4 节（基合蚤属为3 节），内肢3 节。肠管大多不盘曲，其后部无盲囊..........................................................55.第一触角呈吻状尖突。不能活动。嗅毛位于靠近第一触角基部的前侧....象鼻溞科5.第一触角不呈吻状尖突。嗅毛位于第一触角的末端..................66.壳弧非常发达。雌体的第一触角短小，不能活动.......................6.壳弧不发达或缺少，雌雄两性的第一触角长而能动..................77.后腹部上肛刺的周缘有羽状毛，最末一肛刺分叉..............裸腹溞科7.后腹部上肛刺的周缘无羽状毛，也不分叉....................粗毛溞科","explanation":"96\n\n本题考查生物实验。\n\n对比（2）、（3）、（5），应当是先将采集的水样滴在载玻片上，再将棉花纤维放在载玻片的水样中限制动物的运动，然后盖上盖玻片，最后用滤纸把盖玻片多余的水吸走，故排序应当是（5）（3）（2），只有D项符合。\n\n将多余的水吸走后，先用低倍镜观察，再用高倍镜观察。此过程若所采样本中动物数量较少，可用筛绢过滤浓缩或低速离心浓缩后，再制片观察。较大的浮游动物可在体视显微镜下进行解剖与观察。观察分类过程中，先根据动物的形态特征和运动情况，区分其所属门类，再利用检索表进行检索识别。\n\n所以正确顺序为（5）（3）（2）（1）（4）。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22],"answerPages":[28,29]},"idx":95,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220521-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"以下哪项最可能是该实验的目的？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22],"answer":[29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-097-题目-p22-475-573.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-05-21-m96-材料-p21-475-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-05-21-m96-材料-p22-51-382.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"了解淡水浮游生物的主要分类"},{"k":"B","t":"考察淡水浮游生物的主要特征"},{"k":"C","t":"了解淡水浮游生物的检索认识方法"},{"k":"D","t":"熟悉淡水浮游生物的采样方法"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-097-解析-p29-148-246.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下哪项最可能是该实验的目的？（ ）","options":[{"k":"A","t":"了解淡水浮游生物的主要分类"},{"k":"B","t":"考察淡水浮游生物的主要特征"},{"k":"C","t":"了解淡水浮游生物的检索认识方法"},{"k":"D","t":"熟悉淡水浮游生物的采样方法"}],"material":"（五）实验一实验器材：显微镜、载玻片、盖玻片、显微镜、滤纸、棉花纤维等实验步骤：（1）若所采样本中动物数量较少，可以用筛绢过滤浓缩或低速离心浓缩再观察（2）用滤纸把盖玻片多余的水吸走，先用低倍镜观察，再用高倍镜观察（3）将棉纤维放在载玻片上固定生物的运动状态（4）根据动物的形状特征及运动形态，先区别观察动物所属门类，再利用检索表进行检索（5）用吸管吸取水样，滴在载玻片上相关材料：原生动物：原生动物是一类由单细胞构成的微小动物，共有30000 余种，有不少种类生活在淡水中，营浮游生活。\n\n轮虫：多细胞动物，个体微小，身体一般分为头、躯干和尾3 部分。头部具有1～2 圈纤毛组成的轮盘（头冠），躯干常有兜甲，有咀嚼器，尾部末端常有1 对趾。\n\n枝角类：属节肢动物门、甲壳纲、鲤足亚纲、枝角目。通常称水蚤，俗称红虫。体长0.3～3mm，体短而左右侧扁，分节不明显，体被有两瓣透明的介壳，大多数种类的头部有显著的黑色复眼，第二触角发达呈枝角状，胸肢4～6 对，体末端有一爪状尾叉。\n\n桡足类：属节肢动物门、甲壳纲、桡足亚纲。身体纵长，分节明显，头胸部具附肢，腹部无附肢，末端有1 对尾叉，雄性个体头部第一触角左或右、或左右都变形为执握肢（器），雌性腹部两侧或腹面常附有卵囊。\n\n淡水浮游桡足类分为3 个目。\n\n枝角亚目分科检索表1.躯干部与胸肢全为壳瓣所包被....................................21.躯干部与胸肢均裸露与壳瓣之外.........................大眼溞科2.胸肢6 对，同形，均呈叶片状..........................仙达溞总科32.胸肢5～6 对，前两对呈执握状，其余呈叶片状...........盘肠溞总科43.第二触角不论性别，均为双肢型，具游泳刚毛多根..........仙达溞科3.第二触角雌体单肢型，有游泳刚毛3 根；雄体双肢型，共有游泳刚毛5 根（我国尚未发现）...........................................单肢溞科4.第二触角内外肢均为3 节。肠管盘曲，其后部大多有一个盲囊....盘肠溞科4.第二触角外肢4 节（基合蚤属为3 节），内肢3 节。肠管大多不盘曲，其后部无盲囊..........................................................55.第一触角呈吻状尖突。不能活动。嗅毛位于靠近第一触角基部的前侧....象鼻溞科5.第一触角不呈吻状尖突。嗅毛位于第一触角的末端..................66.壳弧非常发达。雌体的第一触角短小，不能活动.......................6.壳弧不发达或缺少，雌雄两性的第一触角长而能动..................77.后腹部上肛刺的周缘有羽状毛，最末一肛刺分叉..............裸腹溞科7.后腹部上肛刺的周缘无羽状毛，也不分叉....................粗毛溞科","explanation":"97\n\n本题考查生物实验。\n\n由上述实验最后一步可知，本实验是通过观察水样中浮游动物的运动形态和主要特征，先区别观察动物所属门类，再利用检索表进行检索，判断其所属的亚目。因此实验的目的是了解淡水浮游生物的检索认识方法，而淡水浮游生物的主要分类及特征是实验前需大致了解，以便于实验时观察和检索。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22],"answerPages":[29]},"idx":96,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220521-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"仙达溞科与裸腹溞科有什么区别？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22,23],"answer":[29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-098-题目-p22-569-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20220521-098-题目-p23-51-308.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-05-21-m96-材料-p21-475-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-05-21-m96-材料-p22-51-382.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"脑肢对数和形状"},{"k":"B","t":"第1 触角是否呈吻状尖突"},{"k":"C","t":"第2 触角肢形和刚毛数"},{"k":"D","t":"脑干部分的分肢是否裸露于甲壳之外"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-098-解析-p29-242-434.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"仙达溞科与裸腹溞科有什么区别？（ ）","options":[{"k":"A","t":"脑肢对数和形状"},{"k":"B","t":"第1 触角是否呈吻状尖突"},{"k":"C","t":"第2 触角肢形和刚毛数"},{"k":"D","t":"脑干部分的分肢是否裸露于甲壳之外"}],"material":"（五）实验一实验器材：显微镜、载玻片、盖玻片、显微镜、滤纸、棉花纤维等实验步骤：（1）若所采样本中动物数量较少，可以用筛绢过滤浓缩或低速离心浓缩再观察（2）用滤纸把盖玻片多余的水吸走，先用低倍镜观察，再用高倍镜观察（3）将棉纤维放在载玻片上固定生物的运动状态（4）根据动物的形状特征及运动形态，先区别观察动物所属门类，再利用检索表进行检索（5）用吸管吸取水样，滴在载玻片上相关材料：原生动物：原生动物是一类由单细胞构成的微小动物，共有30000 余种，有不少种类生活在淡水中，营浮游生活。\n\n轮虫：多细胞动物，个体微小，身体一般分为头、躯干和尾3 部分。头部具有1～2 圈纤毛组成的轮盘（头冠），躯干常有兜甲，有咀嚼器，尾部末端常有1 对趾。\n\n枝角类：属节肢动物门、甲壳纲、鲤足亚纲、枝角目。通常称水蚤，俗称红虫。体长0.3～3mm，体短而左右侧扁，分节不明显，体被有两瓣透明的介壳，大多数种类的头部有显著的黑色复眼，第二触角发达呈枝角状，胸肢4～6 对，体末端有一爪状尾叉。\n\n桡足类：属节肢动物门、甲壳纲、桡足亚纲。身体纵长，分节明显，头胸部具附肢，腹部无附肢，末端有1 对尾叉，雄性个体头部第一触角左或右、或左右都变形为执握肢（器），雌性腹部两侧或腹面常附有卵囊。\n\n淡水浮游桡足类分为3 个目。\n\n枝角亚目分科检索表1.躯干部与胸肢全为壳瓣所包被....................................21.躯干部与胸肢均裸露与壳瓣之外.........................大眼溞科2.胸肢6 对，同形，均呈叶片状..........................仙达溞总科32.胸肢5～6 对，前两对呈执握状，其余呈叶片状...........盘肠溞总科43.第二触角不论性别，均为双肢型，具游泳刚毛多根..........仙达溞科3.第二触角雌体单肢型，有游泳刚毛3 根；雄体双肢型，共有游泳刚毛5 根（我国尚未发现）...........................................单肢溞科4.第二触角内外肢均为3 节。肠管盘曲，其后部大多有一个盲囊....盘肠溞科4.第二触角外肢4 节（基合蚤属为3 节），内肢3 节。肠管大多不盘曲，其后部无盲囊..........................................................55.第一触角呈吻状尖突。不能活动。嗅毛位于靠近第一触角基部的前侧....象鼻溞科5.第一触角不呈吻状尖突。嗅毛位于第一触角的末端..................66.壳弧非常发达。雌体的第一触角短小，不能活动.......................6.壳弧不发达或缺少，雌雄两性的第一触角长而能动..................77.后腹部上肛刺的周缘有羽状毛，最末一肛刺分叉..............裸腹溞科7.后腹部上肛刺的周缘无羽状毛，也不分叉....................粗毛溞科","explanation":"98\n\n本题考查生物实验。\n\nA项错误，根据《枝角亚目分科检索表》仙达泽科属于仙达潘总科，胸肢6对，均呈叶片状；而裸腹潘科属于盘肠泽总科，胸肢5～6对，前两对呈执握状，其余呈叶片状。因此二者胸肢对数可能相同，并不能作为仙达泽科与裸腹科的区别。\n\nB项错误，《枝角亚目分科检索表》未提及仙达泽科的第一触角，无法判断。\n\nC项正确，根据《枝角亚目分科检索表》，仙达泽科的第二触角均为双肢型，具游泳刚毛多根；而裸腹泽科第二触角外肢4节（基合蚤属为3节），内肢3节。二者第二触角肢形和刚毛数存在明显不同，是仙达滏科与裸腹滏科的主要区别。\n\nD项错误，根据《枝角亚目分科检索表》，不论仙达泽科（属仙达泽总科）还是裸腹泽科（属盘肠泽总科），其躯干部与胸肢全为壳瓣所包被。因此躯干部分的分肢是否裸露于甲壳之外不是二者的主要区别。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22,23],"answerPages":[29]},"idx":97,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220521-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"以下哪项最可能是该实验的目的？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-099-题目-p23-304-402.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-05-21-m99-材料-p22-662-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-05-21-m99-材料-p23-51-304.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":99,"options":[{"k":"A","t":"淀粉水解遇碘溶液的颜色变化"},{"k":"B","t":"温度对淀粉酶活力的影响"},{"k":"C","t":"淀粉酶水解淀粉的比例关系"},{"k":"D","t":"淀粉酶水解淀粉的时长"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-099-解析-p29-429-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下哪项最可能是该实验的目的？（ ）","options":[{"k":"A","t":"淀粉水解遇碘溶液的颜色变化"},{"k":"B","t":"温度对淀粉酶活力的影响"},{"k":"C","t":"淀粉酶水解淀粉的比例关系"},{"k":"D","t":"淀粉酶水解淀粉的时长"}],"material":"（六）实验二实验器材及试剂器材：试管、量筒、恒温水浴锅、试管架等试剂：淀粉溶液，淀粉酶溶液、碘溶液实验原理：1.淀粉溶液遇碘会变蓝2.加入淀粉酶溶液后，由于淀粉酶和淀粉发生水解作用，蓝色会变浅3.若时间足够长，淀粉完全水解，则溶液变白色1、按下面表格数据取样分作三个试管1、2、32、摇匀后将试管1、3 号放在37℃恒温水中，将试管2 号放入冰水中，待10 分钟之后将试管2 分为2（1）、2（2）溶液各一半，加碘液观察试管1、2（1）、3 淀粉溶液被淀粉酶水解的程度，并记录结果。将2（2）放入37℃恒温水中10 分钟后在观察淀粉溶液被淀粉酶水解的程度，并记录结果。","explanation":"99\n\n本题考查化学实验。\n\nA项错误，实验当中如要测试淀粉水解遇碘溶液的颜色变化，不需要增加不同温度的实验组。\n\nB项正确，实验当中设置不同样品，放入不同的温度下观察，再观察试管当中的颜色变化，主要就是要验证不同温度对淀粉酶活力的影响。温度过高或过低，会抑制酶的活性，所以三个试管当中的颜色会不同。\n\nC项错误，实验当中如要测试淀粉酶水解淀粉的比例关系，需要增加不同比例的淀粉酶实验组。\n\nD项错误，实验当中并无对淀粉酶水解淀粉的时长统计，所以没有体现出对淀粉酶水解淀粉的时长的目的。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[29]},"idx":98,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220521-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"对照实验","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"对照试管2、3 要研究的问题什么？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220521-100-题目-p23-397-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-05-21-m99-材料-p22-662-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-05-21-m99-材料-p23-51-304.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":99,"options":[{"k":"A","t":"煮沸的淀粉酶溶液是否会使碘变蓝"},{"k":"B","t":"煮沸的淀粉酶溶液是否会提升水解速度"},{"k":"C","t":"煮沸的淀粉酶溶液是否含有淀粉"},{"k":"D","t":"煮沸的淀粉酶溶液是否还有水解活力"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220521-100-解析-p29-554-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"对照试管2、3 要研究的问题什么？（ ）","options":[{"k":"A","t":"煮沸的淀粉酶溶液是否会使碘变蓝"},{"k":"B","t":"煮沸的淀粉酶溶液是否会提升水解速度"},{"k":"C","t":"煮沸的淀粉酶溶液是否含有淀粉"},{"k":"D","t":"煮沸的淀粉酶溶液是否还有水解活力"}],"material":"（六）实验二实验器材及试剂器材：试管、量筒、恒温水浴锅、试管架等试剂：淀粉溶液，淀粉酶溶液、碘溶液实验原理：1.淀粉溶液遇碘会变蓝2.加入淀粉酶溶液后，由于淀粉酶和淀粉发生水解作用，蓝色会变浅3.若时间足够长，淀粉完全水解，则溶液变白色1、按下面表格数据取样分作三个试管1、2、32、摇匀后将试管1、3 号放在37℃恒温水中，将试管2 号放入冰水中，待10 分钟之后将试管2 分为2（1）、2（2）溶液各一半，加碘液观察试管1、2（1）、3 淀粉溶液被淀粉酶水解的程度，并记录结果。将2（2）放入37℃恒温水中10 分钟后在观察淀粉溶液被淀粉酶水解的程度，并记录结果。","explanation":"100\n\n本题考查化学实验。\n\n淀粉酶在100摄氏度煮沸的水中，会失去活性。试管2（1）当中的淀粉酶在冰水当中，会降低它的活性。\n\n试管2（2）放入37°C恒温水当中的淀粉酶活性增强。对照说明，在冷水当中的淀粉酶，还保留活性。而热水当中的淀粉酶失去活性。所以这两组对照实验，就是为了验证煮沸的淀粉酶溶液是否还有水解活性。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2022/2022-05-21/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[29]},"idx":99,"pid":"pd5f69523eb","sourceYears":[2022]},{"qid":"sy-c-20220917-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（7）以免白白耗费体力并错失获得食物和配偶的机会","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22,23],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-096-题目-p22-740-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20220917-096-题目-p23-51-261.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-09-17-m96-材料-p22-288-740.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"（6）（2）（7）"},{"k":"B","t":"（5）（1）（6）"},{"k":"C","t":"（2）（7）（5）"},{"k":"D","t":"（3）（7）（1）"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-096-解析-p31-537-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列语句经恰当排序后可构成文中省略的第三段，位于段落中间的三句最可能是（ ）。\n\n（1）这是动物在漫长的进化过程中逐渐形成的本能（2）另一方面，它们不能对非危险性线索，比如飞过的昆虫做出过度反应（3）一方面，它们需要快速检测到逼近的天敌（4）对动物的生存和繁衍至关重要（5）自然环境中充斥着各种复杂的感觉线索，动物需要基于这些线索做出判断（6）采取恰当的防御行为，来确保自身的安全（7）以免白白耗费体力并错失获得食物和配偶的机会","options":[{"k":"A","t":"（6）（2）（7）"},{"k":"B","t":"（5）（1）（6）"},{"k":"C","t":"（2）（7）（5）"},{"k":"D","t":"（3）（7）（1）"}],"material":"（五）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理，选出最符合每道题要求的一项。\n\n在复杂多变的自然环境中，大脑如何“快速”“简洁”“精准”地判断天敌信号，产生快速且合适的防御反应是物种得以生存与繁衍的重要前提。\n\n近日，某研究团队发现动物大脑快速防御天敌反应的“简单”策略。该研究揭示了小鼠的大脑在处理视觉线索时存在一个用于检测天敌的“警戒范围”通过这种方式可以快速识别危险信号，并诱发防御反应。\n\n······（此处略去第三段）视觉线索是动物快速检测危险的重要依据，此前研究常用一个逐渐扩大的阴影圆盘来模拟捕食者的攻击，并成功诱发了小鼠的本能防御反应。这说明视觉系统在判断危险信号时可能会忽略掉一些细节，只基于某些关键视觉线索进行判断。\n\n小鼠通过视觉刺激是否处于警戒范围来判断危险程度，并采用适当的行为反应。\n\n那么动物到底基于哪些视觉线索来判断风险，又有哪些线索是不需要过多关注的呢？在研究过程中，研究团队开发了基于红外触摸屏的小动物行为自动监测系统，通过给小鼠设定视觉刺激，鼠在遇到视觉刺激时的反应参数。\n\n该自动检测系统可以记录小鼠在装置内的行为数据，例如小鼠大小、位置以及对应的时间，根据这些数据可以计算小鼠逃跑的速度、僵直的时间、站立的次数等等，数据的采集和后续的计算和统计都可由程序完成，该系统基本实现了小鼠行为数据采集和分析的自动化。\n\n研究人员通过监测系统给小鼠呈现一系列以不同速度扩大、具有不同大小的圆盘阴影，记录并量化分析了小鼠由这些视觉刺激引发的行为反应，包括逃跑、僵直和站立等。团队发现，小鼠对圆盘阴影的大小变化和扩大速度的检测存在一个“警戒范围”，即大小处于 至 ，扩大速度在 至 这个范围内的圆盘阴影更容易引发强烈的逃跑反应。\n\n基于研究中发现的“警戒范围”在进一步的验证中，研究团队根据动物大小和来袭速度，模拟仓鹗、蜻蜓、苍蝇等动物对小鼠的视觉刺激。\n\n团队发现捕食鼠类的猛禽，如黑翅鸢、仓鸮等，它们在捕食过程中的影像基本符合小鼠的“警戒范围”，而低危险性的视觉线索，如苍蝇、蜻蜓等昆虫靠近的影像，则与“警戒范围”不重合或只有很少的重合。由此推测，“警戒范围”代表发动攻击的捕食者所具有的共同视觉特征。\n\n经过系列实验后，团队得出小鼠检测捕食者的策略：小鼠基于视觉线索是否处于警戒范围来做出反应，而不是为不同天敌“定制”特定的检测机制，这个简单的策略有助于小鼠快速且精准地辨识真正的危险。该研究将有助于理解大脑处理危险信号的神经机制及其进化意义。","explanation":"（备注：题干表述不严谨，“任意2块作物种植区域”，实际指“任意2种作物种植区域”。）96\n\n本题考查生物实验。\n\n题干第二段与第四段均是围绕小鼠大脑如何处理视觉线索展开，再结合本题中的7句话，可知第三段是在分析小鼠大脑如何处理视觉线索。\n\n观察本题中的7句话，（1）－（4）句中存在指代词或缺少主语，明显不适合作首句；（6）、（7）句则是具体的防御反应，也不适合作首句，故可判断首句为（5）。\n\n（5）句引出了“感觉线索”，（3）、（2）句从两方面对这些“感觉线索”展开论述，而（6）、（7）句则恰好是针对这两方面分别对应的防御反应。故具体展开论述过程的语句排序应当是（3）（6）（2）（7）。\n\n（1）句通过“这是”将上述小鼠对危险信号的处理概括为动物本能，（4）句则是对这项动物本能的重要性进行总结，二句作为结尾句，排序为（1）（4）。\n\n综上所述，本题中7句话的正确排序应当为（5）（3）（6）（2）（7）（1）（4），因此，位于段落中间的三句最可能是（6）（2）（7）。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[22,23],"answerPages":[31]},"idx":95,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-c-20220917-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"本实验的研究主旨是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-097-题目-p23-257-355.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-09-17-m96-材料-p22-288-740.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"动物大脑如何判断天敌信号"},{"k":"B","t":"小鼠对捕食者基于何种检测、防御反应策略"},{"k":"C","t":"动物大脑处理危险信号的神经机制及其进化策略"},{"k":"D","t":"小鼠基于哪些视觉线索来判断风险，避免过多关注"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-097-解析-p32-40-231.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"本实验的研究主旨是（ ）。","options":[{"k":"A","t":"动物大脑如何判断天敌信号"},{"k":"B","t":"小鼠对捕食者基于何种检测、防御反应策略"},{"k":"C","t":"动物大脑处理危险信号的神经机制及其进化策略"},{"k":"D","t":"小鼠基于哪些视觉线索来判断风险，避免过多关注"}],"material":"（五）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理，选出最符合每道题要求的一项。\n\n在复杂多变的自然环境中，大脑如何“快速”“简洁”“精准”地判断天敌信号，产生快速且合适的防御反应是物种得以生存与繁衍的重要前提。\n\n近日，某研究团队发现动物大脑快速防御天敌反应的“简单”策略。该研究揭示了小鼠的大脑在处理视觉线索时存在一个用于检测天敌的“警戒范围”通过这种方式可以快速识别危险信号，并诱发防御反应。\n\n······（此处略去第三段）视觉线索是动物快速检测危险的重要依据，此前研究常用一个逐渐扩大的阴影圆盘来模拟捕食者的攻击，并成功诱发了小鼠的本能防御反应。这说明视觉系统在判断危险信号时可能会忽略掉一些细节，只基于某些关键视觉线索进行判断。\n\n小鼠通过视觉刺激是否处于警戒范围来判断危险程度，并采用适当的行为反应。\n\n那么动物到底基于哪些视觉线索来判断风险，又有哪些线索是不需要过多关注的呢？在研究过程中，研究团队开发了基于红外触摸屏的小动物行为自动监测系统，通过给小鼠设定视觉刺激，鼠在遇到视觉刺激时的反应参数。\n\n该自动检测系统可以记录小鼠在装置内的行为数据，例如小鼠大小、位置以及对应的时间，根据这些数据可以计算小鼠逃跑的速度、僵直的时间、站立的次数等等，数据的采集和后续的计算和统计都可由程序完成，该系统基本实现了小鼠行为数据采集和分析的自动化。\n\n研究人员通过监测系统给小鼠呈现一系列以不同速度扩大、具有不同大小的圆盘阴影，记录并量化分析了小鼠由这些视觉刺激引发的行为反应，包括逃跑、僵直和站立等。团队发现，小鼠对圆盘阴影的大小变化和扩大速度的检测存在一个“警戒范围”，即大小处于 至 ，扩大速度在 至 这个范围内的圆盘阴影更容易引发强烈的逃跑反应。\n\n基于研究中发现的“警戒范围”在进一步的验证中，研究团队根据动物大小和来袭速度，模拟仓鹗、蜻蜓、苍蝇等动物对小鼠的视觉刺激。\n\n团队发现捕食鼠类的猛禽，如黑翅鸢、仓鸮等，它们在捕食过程中的影像基本符合小鼠的“警戒范围”，而低危险性的视觉线索，如苍蝇、蜻蜓等昆虫靠近的影像，则与“警戒范围”不重合或只有很少的重合。由此推测，“警戒范围”代表发动攻击的捕食者所具有的共同视觉特征。\n\n经过系列实验后，团队得出小鼠检测捕食者的策略：小鼠基于视觉线索是否处于警戒范围来做出反应，而不是为不同天敌“定制”特定的检测机制，这个简单的策略有助于小鼠快速且精准地辨识真正的危险。该研究将有助于理解大脑处理危险信号的神经机制及其进化意义。","explanation":"97\n\n本题考查生物实验。\n\nA项错误，“动物大脑”扩大范围，且本实验中研究的是检测捕食者的影像是否符合小鼠的“警戒范围”，而非判断捕食者是否是天敌。\n\nB项正确，题干结尾指出：经过系列实验后，团队得出小鼠检测捕食者的策略，小鼠通过检测视觉线索是否处于警戒范围来做出反应。因此，实验研究的主旨是小鼠对捕食者基于何种检测、防御反应策略。\n\nC项错误，“动物大脑”扩大范围，且本实验未涉及大脑的进化策略。\n\nD项错误，小鼠判断风险的最主要目的是快速且精准地辨识真正的危险，既要采取恰当的防御行为，又要避免过度反应。因此避免过多关注只是小鼠检测捕食者的策略的一个方面。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[32]},"idx":96,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-c-20220917-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"（4）天敌的数额特征","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-098-题目-p23-350-511.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-09-17-m96-材料-p22-288-740.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"（1）（2）"},{"k":"B","t":"（2）（3）"},{"k":"C","t":"（3）（4）"},{"k":"D","t":"（1）（4）"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-098-解析-p32-226-324.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"小鼠的“警戒范围”主要包括（ ）。\n\n（1）影像的视觉刺激（2）视觉大小的变化（3）阴影的扩大速度（4）天敌的数额特征","options":[{"k":"A","t":"（1）（2）"},{"k":"B","t":"（2）（3）"},{"k":"C","t":"（3）（4）"},{"k":"D","t":"（1）（4）"}],"material":"（五）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理，选出最符合每道题要求的一项。\n\n在复杂多变的自然环境中，大脑如何“快速”“简洁”“精准”地判断天敌信号，产生快速且合适的防御反应是物种得以生存与繁衍的重要前提。\n\n近日，某研究团队发现动物大脑快速防御天敌反应的“简单”策略。该研究揭示了小鼠的大脑在处理视觉线索时存在一个用于检测天敌的“警戒范围”通过这种方式可以快速识别危险信号，并诱发防御反应。\n\n······（此处略去第三段）视觉线索是动物快速检测危险的重要依据，此前研究常用一个逐渐扩大的阴影圆盘来模拟捕食者的攻击，并成功诱发了小鼠的本能防御反应。这说明视觉系统在判断危险信号时可能会忽略掉一些细节，只基于某些关键视觉线索进行判断。\n\n小鼠通过视觉刺激是否处于警戒范围来判断危险程度，并采用适当的行为反应。\n\n那么动物到底基于哪些视觉线索来判断风险，又有哪些线索是不需要过多关注的呢？在研究过程中，研究团队开发了基于红外触摸屏的小动物行为自动监测系统，通过给小鼠设定视觉刺激，鼠在遇到视觉刺激时的反应参数。\n\n该自动检测系统可以记录小鼠在装置内的行为数据，例如小鼠大小、位置以及对应的时间，根据这些数据可以计算小鼠逃跑的速度、僵直的时间、站立的次数等等，数据的采集和后续的计算和统计都可由程序完成，该系统基本实现了小鼠行为数据采集和分析的自动化。\n\n研究人员通过监测系统给小鼠呈现一系列以不同速度扩大、具有不同大小的圆盘阴影，记录并量化分析了小鼠由这些视觉刺激引发的行为反应，包括逃跑、僵直和站立等。团队发现，小鼠对圆盘阴影的大小变化和扩大速度的检测存在一个“警戒范围”，即大小处于 至 ，扩大速度在 至 这个范围内的圆盘阴影更容易引发强烈的逃跑反应。\n\n基于研究中发现的“警戒范围”在进一步的验证中，研究团队根据动物大小和来袭速度，模拟仓鹗、蜻蜓、苍蝇等动物对小鼠的视觉刺激。\n\n团队发现捕食鼠类的猛禽，如黑翅鸢、仓鸮等，它们在捕食过程中的影像基本符合小鼠的“警戒范围”，而低危险性的视觉线索，如苍蝇、蜻蜓等昆虫靠近的影像，则与“警戒范围”不重合或只有很少的重合。由此推测，“警戒范围”代表发动攻击的捕食者所具有的共同视觉特征。\n\n经过系列实验后，团队得出小鼠检测捕食者的策略：小鼠基于视觉线索是否处于警戒范围来做出反应，而不是为不同天敌“定制”特定的检测机制，这个简单的策略有助于小鼠快速且精准地辨识真正的危险。该研究将有助于理解大脑处理危险信号的神经机制及其进化意义。","explanation":"98\n\n本题考查生物实验。\n\n题干第八段指出，小鼠对圆盘阴影的大小变化和扩大速度的检测存在一个“警戒范围”，即大小处于10°至40°，扩大速度在57°/s至320°/s这个范围内的圆盘阴影更容易引发强烈的逃跑反应。可知小鼠的“警戒范围”主要包括视觉大小的变化、阴影的扩大速度两方面，即对应本题中的（2）和（3）。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[32]},"idx":97,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-c-20220917-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"本实验通过以下哪项来判断小鼠应对天敌所采取的策略？（ ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-099-题目-p23-506-604.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-09-17-m96-材料-p22-288-740.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"天敌种类"},{"k":"B","t":"视觉刺激"},{"k":"C","t":"体态行为"},{"k":"D","t":"危险程度"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-099-解析-p32-320-448.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"本实验通过以下哪项来判断小鼠应对天敌所采取的策略？（ ）","options":[{"k":"A","t":"天敌种类"},{"k":"B","t":"视觉刺激"},{"k":"C","t":"体态行为"},{"k":"D","t":"危险程度"}],"material":"（五）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理，选出最符合每道题要求的一项。\n\n在复杂多变的自然环境中，大脑如何“快速”“简洁”“精准”地判断天敌信号，产生快速且合适的防御反应是物种得以生存与繁衍的重要前提。\n\n近日，某研究团队发现动物大脑快速防御天敌反应的“简单”策略。该研究揭示了小鼠的大脑在处理视觉线索时存在一个用于检测天敌的“警戒范围”通过这种方式可以快速识别危险信号，并诱发防御反应。\n\n······（此处略去第三段）视觉线索是动物快速检测危险的重要依据，此前研究常用一个逐渐扩大的阴影圆盘来模拟捕食者的攻击，并成功诱发了小鼠的本能防御反应。这说明视觉系统在判断危险信号时可能会忽略掉一些细节，只基于某些关键视觉线索进行判断。\n\n小鼠通过视觉刺激是否处于警戒范围来判断危险程度，并采用适当的行为反应。\n\n那么动物到底基于哪些视觉线索来判断风险，又有哪些线索是不需要过多关注的呢？在研究过程中，研究团队开发了基于红外触摸屏的小动物行为自动监测系统，通过给小鼠设定视觉刺激，鼠在遇到视觉刺激时的反应参数。\n\n该自动检测系统可以记录小鼠在装置内的行为数据，例如小鼠大小、位置以及对应的时间，根据这些数据可以计算小鼠逃跑的速度、僵直的时间、站立的次数等等，数据的采集和后续的计算和统计都可由程序完成，该系统基本实现了小鼠行为数据采集和分析的自动化。\n\n研究人员通过监测系统给小鼠呈现一系列以不同速度扩大、具有不同大小的圆盘阴影，记录并量化分析了小鼠由这些视觉刺激引发的行为反应，包括逃跑、僵直和站立等。团队发现，小鼠对圆盘阴影的大小变化和扩大速度的检测存在一个“警戒范围”，即大小处于 至 ，扩大速度在 至 这个范围内的圆盘阴影更容易引发强烈的逃跑反应。\n\n基于研究中发现的“警戒范围”在进一步的验证中，研究团队根据动物大小和来袭速度，模拟仓鹗、蜻蜓、苍蝇等动物对小鼠的视觉刺激。\n\n团队发现捕食鼠类的猛禽，如黑翅鸢、仓鸮等，它们在捕食过程中的影像基本符合小鼠的“警戒范围”，而低危险性的视觉线索，如苍蝇、蜻蜓等昆虫靠近的影像，则与“警戒范围”不重合或只有很少的重合。由此推测，“警戒范围”代表发动攻击的捕食者所具有的共同视觉特征。\n\n经过系列实验后，团队得出小鼠检测捕食者的策略：小鼠基于视觉线索是否处于警戒范围来做出反应，而不是为不同天敌“定制”特定的检测机制，这个简单的策略有助于小鼠快速且精准地辨识真正的危险。该研究将有助于理解大脑处理危险信号的神经机制及其进化意义。","explanation":"99\n\n本题考查生物实验。\n\nA项错误，题干最后一段指出，小鼠基于视觉线索是否处于警戒范围来做出反应，而不是为不同天敌“定制”特定的检测机制。即小鼠不会区分天敌的种类。\n\nB项正确，D项错误，实验中，小鼠通过视觉刺激是否处于警戒范围来判断危险程度，进而采取应对策略，即大小处于10°至40°，扩大速度在57/s至320°s这个范围内的圆盘阴影更容易引发强烈的逃跑反应。\n\nC项错误，小鼠“警戒范围”主要包括视觉大小的变化、阴影的扩大速度两方面，与体态行为无关。\n\n故正确答案为 B。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[32]},"idx":98,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-c-20220917-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验结论","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"本实验得出结论所采用的主要研究方法是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[23],"answer":[32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20220917-100-题目-p23-600-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-09-17-m96-材料-p22-288-740.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"求同法（结果出现的若干不同场合中探求其共同因素）"},{"k":"B","t":"求异法（在结果出现和不出现的两个尽可能相同的场合中探求其唯一的差异因素）"},{"k":"C","t":"共变法（在结果发生变化的若干不同场合中探求与其共同变化的因素）"},{"k":"D","t":"剩余法（在剔除已知的具有因果联系的关系之外，在剩余结果和剩余因素之间探求其联系）"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20220917-100-解析-p32-444-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"本实验得出结论所采用的主要研究方法是（ ）。","options":[{"k":"A","t":"求同法（结果出现的若干不同场合中探求其共同因素）"},{"k":"B","t":"求异法（在结果出现和不出现的两个尽可能相同的场合中探求其唯一的差异因素）"},{"k":"C","t":"共变法（在结果发生变化的若干不同场合中探求与其共同变化的因素）"},{"k":"D","t":"剩余法（在剔除已知的具有因果联系的关系之外，在剩余结果和剩余因素之间探求其联系）"}],"material":"（五）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理，选出最符合每道题要求的一项。\n\n在复杂多变的自然环境中，大脑如何“快速”“简洁”“精准”地判断天敌信号，产生快速且合适的防御反应是物种得以生存与繁衍的重要前提。\n\n近日，某研究团队发现动物大脑快速防御天敌反应的“简单”策略。该研究揭示了小鼠的大脑在处理视觉线索时存在一个用于检测天敌的“警戒范围”通过这种方式可以快速识别危险信号，并诱发防御反应。\n\n······（此处略去第三段）视觉线索是动物快速检测危险的重要依据，此前研究常用一个逐渐扩大的阴影圆盘来模拟捕食者的攻击，并成功诱发了小鼠的本能防御反应。这说明视觉系统在判断危险信号时可能会忽略掉一些细节，只基于某些关键视觉线索进行判断。\n\n小鼠通过视觉刺激是否处于警戒范围来判断危险程度，并采用适当的行为反应。\n\n那么动物到底基于哪些视觉线索来判断风险，又有哪些线索是不需要过多关注的呢？在研究过程中，研究团队开发了基于红外触摸屏的小动物行为自动监测系统，通过给小鼠设定视觉刺激，鼠在遇到视觉刺激时的反应参数。\n\n该自动检测系统可以记录小鼠在装置内的行为数据，例如小鼠大小、位置以及对应的时间，根据这些数据可以计算小鼠逃跑的速度、僵直的时间、站立的次数等等，数据的采集和后续的计算和统计都可由程序完成，该系统基本实现了小鼠行为数据采集和分析的自动化。\n\n研究人员通过监测系统给小鼠呈现一系列以不同速度扩大、具有不同大小的圆盘阴影，记录并量化分析了小鼠由这些视觉刺激引发的行为反应，包括逃跑、僵直和站立等。团队发现，小鼠对圆盘阴影的大小变化和扩大速度的检测存在一个“警戒范围”，即大小处于 至 ，扩大速度在 至 这个范围内的圆盘阴影更容易引发强烈的逃跑反应。\n\n基于研究中发现的“警戒范围”在进一步的验证中，研究团队根据动物大小和来袭速度，模拟仓鹗、蜻蜓、苍蝇等动物对小鼠的视觉刺激。\n\n团队发现捕食鼠类的猛禽，如黑翅鸢、仓鸮等，它们在捕食过程中的影像基本符合小鼠的“警戒范围”，而低危险性的视觉线索，如苍蝇、蜻蜓等昆虫靠近的影像，则与“警戒范围”不重合或只有很少的重合。由此推测，“警戒范围”代表发动攻击的捕食者所具有的共同视觉特征。\n\n经过系列实验后，团队得出小鼠检测捕食者的策略：小鼠基于视觉线索是否处于警戒范围来做出反应，而不是为不同天敌“定制”特定的检测机制，这个简单的策略有助于小鼠快速且精准地辨识真正的危险。该研究将有助于理解大脑处理危险信号的神经机制及其进化意义。","explanation":"100\n\n本题考查生物实验。\n\nA项错误，求同法是要在不同实验过程中找出相同的实验因素，由此推测引起结果的原因就是这个相同的实验因素，因此求同法属于通过定性分析找出某一因素。但本题是通过改变特定因素的值，进而确定了小鼠的警戒范围，属于对特定因素的定量分析，因此不属于求同法。\n\nB项错误，本题实验存在视觉大小的变化、阴影的扩大速度两个变量，不符合“唯一的差异因素”，不属于求异法。\n\nC项正确，本实验中，小鼠的逃跑反应是实验的研究结果，实验中变化的因素则是圆盘阴影的大小变化和扩大速度，处于特定范围内的圆盘阴影更容易引发强烈的逃跑反应，因此可以判断圆盘阴影的大小变化和扩大速度的变化会对小鼠的逃跑反应产生影响，即存在共同变动的关系，应用了共变法。\n\nD项错误，本题实验中并未分析已知的因果关系，也就不符合在排除已知因果的情况下探求其他因果关系，不属于剩余法。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2022/2022-09-17/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[23],"answerPages":[32]},"idx":99,"pid":"p43b2f27e6f","sourceYears":[2022]},{"qid":"sy-c-20221112-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"下列实验步骤的顺序是错误的，正确的顺序是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[21],"answer":[30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-096-题目-p21-132-230.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-11-12-m96-材料-p20-460-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-11-12-m96-材料-p21-51-132.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"②④⑤①⑥③"},{"k":"B","t":"②⑥①④⑤③"},{"k":"C","t":"④②⑥①⑤③"},{"k":"D","t":"④⑥③①②⑤"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-096-解析-p30-272-400.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列实验步骤的顺序是错误的，正确的顺序是（ ）。","options":[{"k":"A","t":"②④⑤①⑥③"},{"k":"B","t":"②⑥①④⑤③"},{"k":"C","t":"④②⑥①⑤③"},{"k":"D","t":"④⑥③①②⑤"}],"material":"（五）【实验原理】利用油酸酒精溶液平静的水面上形成单分子油膜，将油酸分子看作球形，测出一定体积油酸溶液水面上形成的油膜面积，用 计算出油膜的厚度，其中 为一滴油酸溶液中所含油酸的体积， 为油膜面积，这个厚度就近似等于油酸分子的直径。\n\n【实验器材】盛水浅盘，滴管，试剂瓶，坐标纸，玻璃板，痱子粉，油酸酒精溶液，量筒，彩笔。\n\n【实验步骤】\n\n①油酸薄膜形状稳定后，将一块较大的玻璃板盖在浅盘上，用彩笔将油酸薄膜的形状画在玻璃板上。\n\n②用滴管向量筒中滴入 滴配制好的油酸酒精溶液，算出每滴油酸酒精溶液的体积。\n\n③根据油酸酒精溶液的浓度，算出一滴溶液中纯油酸的体积，进而算出油酸薄膜的厚度。\n\n④取体积为 的油酸溶于酒精中，制成体积为 的油酸酒精溶液。往边长约为30 40cm 的浅盘中倒入约2cm深的水，然后将痱子粉均匀地撒在水面上。\n\n⑤将画有油酸薄膜轮廓的玻璃板放在坐标纸上，算出油酸薄膜的面积 。\n\n⑥用滴管向水面上滴入一滴配制好的油酸酒精溶液，油酸就在水面上慢慢散开，形成单分子油膜。","explanation":"96\n\n本题考查物理实验。\n\n观察各选项第一步，步骤④为配置油酸酒精溶液，步骤②为计算油酸酒精溶液的体积，步骤④应在步骤②之前，排除A、B项。\n\n对比C、D项最后一步，步骤③为计算油酸薄膜的厚度d，步骤③为计算油膜面积S，根据实验原理，应先计算油膜面积S，再根据公式d：\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/策略选择.md","module":"综合分析","sourceModule":"策略选择","sourceType":"实验设计","questionPages":[21],"answerPages":[30]},"idx":95,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"如果实验过程中出现下列误差，导致计算的分子直径数值偏小的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[21],"answer":[30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-097-题目-p21-226-324.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-11-12-m96-材料-p20-460-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-11-12-m96-材料-p21-51-132.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"痱子粉的用量过大，导数油酸分子被过分挤压"},{"k":"B","t":"油酸尚未完全散开便开始绘制油酸薄膜轮廓"},{"k":"C","t":"用滴管向量筒滴入 滴油酸酒精溶液，计算时仅按n 滴计算"},{"k":"D","t":"利用坐标纸计算油膜面积时，多计算了轮廓内单位正方形的数量"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-097-解析-p30-396-588.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"如果实验过程中出现下列误差，导致计算的分子直径数值偏小的是（ ）。","options":[{"k":"A","t":"痱子粉的用量过大，导数油酸分子被过分挤压"},{"k":"B","t":"油酸尚未完全散开便开始绘制油酸薄膜轮廓"},{"k":"C","t":"用滴管向量筒滴入 滴油酸酒精溶液，计算时仅按n 滴计算"},{"k":"D","t":"利用坐标纸计算油膜面积时，多计算了轮廓内单位正方形的数量"}],"material":"（五）【实验原理】利用油酸酒精溶液平静的水面上形成单分子油膜，将油酸分子看作球形，测出一定体积油酸溶液水面上形成的油膜面积，用 计算出油膜的厚度，其中 为一滴油酸溶液中所含油酸的体积， 为油膜面积，这个厚度就近似等于油酸分子的直径。\n\n【实验器材】盛水浅盘，滴管，试剂瓶，坐标纸，玻璃板，痱子粉，油酸酒精溶液，量筒，彩笔。\n\n【实验步骤】\n\n①油酸薄膜形状稳定后，将一块较大的玻璃板盖在浅盘上，用彩笔将油酸薄膜的形状画在玻璃板上。\n\n②用滴管向量筒中滴入 滴配制好的油酸酒精溶液，算出每滴油酸酒精溶液的体积。\n\n③根据油酸酒精溶液的浓度，算出一滴溶液中纯油酸的体积，进而算出油酸薄膜的厚度。\n\n④取体积为 的油酸溶于酒精中，制成体积为 的油酸酒精溶液。往边长约为30 40cm 的浅盘中倒入约2cm深的水，然后将痱子粉均匀地撒在水面上。\n\n⑤将画有油酸薄膜轮廓的玻璃板放在坐标纸上，算出油酸薄膜的面积 。\n\n⑥用滴管向水面上滴入一滴配制好的油酸酒精溶液，油酸就在水面上慢慢散开，形成单分子油膜。","explanation":"97\n\n本题考查物理实验。\n\n根据实验原理及公式d：若计算的分子直径数值d偏小，则可能的原因是测算的油酸酒精体积V偏小或S计算的油膜面积S偏大。\n\nA、B项错误，油酸分子被痱子粉过分挤压、油酸尚未完全散开便开始绘制油酸薄膜轮廓，均会导致测算的油膜面积S偏小，最终计算出的分子直径d偏大。\n\nC项错误，实际滴入了(n+1)滴油酸酒精溶液，而计算每滴油酸酒精溶液V时仅按n滴计算，则会使V的数值偏大，最终会导致计算的分子直径d偏大。\n\nD项正确，利用坐标纸计算油膜面积时，多计算轮廓内单位正方形的数量会导致测算的油膜面积S偏大，最终计算出的分子直径d偏小。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/策略选择.md","module":"综合分析","sourceModule":"策略选择","sourceType":"实验设计","questionPages":[21],"answerPages":[30]},"idx":96,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"已知 滴配制好的油酸酒精溶液的体积为 ，则油酸分子的直径为（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[21,22],"answer":[30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-098-题目-p21-319-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20221112-098-题目-p22-51-90.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-11-12-m96-材料-p20-460-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-11-12-m96-材料-p21-51-132.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"- **B**."},{"k":"B","t":"B"},{"k":"C","t":"- **D**."},{"k":"D","t":"D"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-098-解析-p30-584-728.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"已知 滴配制好的油酸酒精溶液的体积为 ，则油酸分子的直径为（ ）。","options":[{"k":"A","t":"- **B**."},{"k":"B","t":"B"},{"k":"C","t":"- **D**."},{"k":"D","t":"D"}],"material":"（五）【实验原理】利用油酸酒精溶液平静的水面上形成单分子油膜，将油酸分子看作球形，测出一定体积油酸溶液水面上形成的油膜面积，用 计算出油膜的厚度，其中 为一滴油酸溶液中所含油酸的体积， 为油膜面积，这个厚度就近似等于油酸分子的直径。\n\n【实验器材】盛水浅盘，滴管，试剂瓶，坐标纸，玻璃板，痱子粉，油酸酒精溶液，量筒，彩笔。\n\n【实验步骤】\n\n①油酸薄膜形状稳定后，将一块较大的玻璃板盖在浅盘上，用彩笔将油酸薄膜的形状画在玻璃板上。\n\n②用滴管向量筒中滴入 滴配制好的油酸酒精溶液，算出每滴油酸酒精溶液的体积。\n\n③根据油酸酒精溶液的浓度，算出一滴溶液中纯油酸的体积，进而算出油酸薄膜的厚度。\n\n④取体积为 的油酸溶于酒精中，制成体积为 的油酸酒精溶液。往边长约为30 40cm 的浅盘中倒入约2cm深的水，然后将痱子粉均匀地撒在水面上。\n\n⑤将画有油酸薄膜轮廓的玻璃板放在坐标纸上，算出油酸薄膜的面积 。\n\n⑥用滴管向水面上滴入一滴配制好的油酸酒精溶液，油酸就在水面上慢慢散开，形成单分子油膜。","explanation":"98\n\n本题考查物理实验。\n\nV2n滴配制好的油酸酒精溶液的体积为V，则每滴油酸酒精溶液的体积为VoV2Vo那么一滴溶液中纯油酸的体积就是VoV2则油酸分子的直径d：nSV\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/策略选择.md","module":"综合分析","sourceModule":"策略选择","sourceType":"实验设计","questionPages":[21,22],"answerPages":[30]},"idx":97,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"下列选项中，最有可能是本次实验目的的是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22],"answer":[30,31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-099-题目-p22-85-183.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-11-12-m99-材料-p21-475-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-11-12-m99-材料-p22-51-85.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":99,"options":[{"k":"A","t":"观察DNA 和RNA 在细胞中的分布"},{"k":"B","t":"验证甲基绿吡罗红染色剂对细胞结构的染色效果"},{"k":"C","t":"探究DNA 和RNA 的化学特性"},{"k":"D","t":"比较甲基绿吡罗红染色剂对细胞核和细胞质染色的异同"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-099-解析-p30-724-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20221112-099-解析-p31-51-136.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列选项中，最有可能是本次实验目的的是（ ）。","options":[{"k":"A","t":"观察DNA 和RNA 在细胞中的分布"},{"k":"B","t":"验证甲基绿吡罗红染色剂对细胞结构的染色效果"},{"k":"C","t":"探究DNA 和RNA 的化学特性"},{"k":"D","t":"比较甲基绿吡罗红染色剂对细胞核和细胞质染色的异同"}],"material":"（六）（二）【实验原理】甲基绿、吡罗红与DNA、RNA 的亲和力不同，甲基绿使DNA 呈现绿色，吡罗红使RNA 呈现红色。\n\n【实验器材及试剂】大小烧杯，温度计，浦管，消毒牙签，载玻片，盖玻片，铁架台，石棉网，火柴，酒精灯，吸水纸，显微镜，甲基绿吡罗红染色剂，质量分数为 的 溶液（生理盐水），质量分数为 的盐酸，蒸馏水【实验步骤】\n\n①在载玻片上用滴管滴一滴生理盐水，用牙签在口腔一侧轻轻刮几下，再把牙签浸入载玻片的生理盐水中，使细胞留在载玻片上，点燃酒精灯烘干载玻片。\n\n②在小烧杯中加入30ml 质量分数为 的盐酸，再取一个大烧杯，大烧杯内装 温水，然后把小烧杯放入大烧杯内，最后把烘干好的载玻片放入小烧杯内，要使载玻片上的细胞都浸入盐酸溶液中，保温5分钟。\n\n③用蒸馏水的缓水流冲洗载玻片10秒。\n\n④用吸水纸吸去载玻片上的水分，将甲基绿吡罗红混合染色剂滴2滴在载玻片上，染色5分钟。再用吸水纸吸去多余染色剂，盖上盖玻片。\n\n⑤先用低倍镜观察，选择染色均匀、色泽浅的区域，移至视野中央，将物调节清晰，然后用高倍镜观察，调节细准焦螺旋，观察细胞核和细胞质的染色情况。\n\n【实验结果】细胞核区域呈绿色，细胞质区域呈红色。","explanation":"99\n\n本题考查生物实验。\n\n吡罗红可将RNA染成红色，而甲基绿可将DNA染成绿色。根据实验结果，细胞核区域呈绿色，细胞质区域呈红色，可以得出 DNA分布在细胞核区域，RNA 分布在细胞质区域，因此实验目的是观察 DNA 和 RNA 在细胞中的分布。\n\n故正确答案为 A。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/策略选择.md","module":"综合分析","sourceModule":"策略选择","sourceType":"实验设计","questionPages":[22],"answerPages":[30,31]},"idx":98,"pid":"p2065d6d72f","sourceYears":[2022]},{"qid":"sy-c-20221112-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"实验步骤③最有可能起到的作用是（ ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[22],"answer":[31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20221112-100-题目-p22-179-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2022-11-12-m99-材料-p21-475-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2022-11-12-m99-材料-p22-51-85.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":99,"options":[{"k":"A","t":"防止盐酸破坏细胞结构而影响观察结果"},{"k":"B","t":"防止盐酸改变细胞酸碱性影响观察结果"},{"k":"C","t":"防止细胞过于干燥无法实现有效染色"},{"k":"D","t":"恢复细胞活性促进与染色剂有效结合"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20221112-100-解析-p31-132-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"实验步骤③最有可能起到的作用是（ ）。","options":[{"k":"A","t":"防止盐酸破坏细胞结构而影响观察结果"},{"k":"B","t":"防止盐酸改变细胞酸碱性影响观察结果"},{"k":"C","t":"防止细胞过于干燥无法实现有效染色"},{"k":"D","t":"恢复细胞活性促进与染色剂有效结合"}],"material":"（六）（二）【实验原理】甲基绿、吡罗红与DNA、RNA 的亲和力不同，甲基绿使DNA 呈现绿色，吡罗红使RNA 呈现红色。\n\n【实验器材及试剂】大小烧杯，温度计，浦管，消毒牙签，载玻片，盖玻片，铁架台，石棉网，火柴，酒精灯，吸水纸，显微镜，甲基绿吡罗红染色剂，质量分数为 的 溶液（生理盐水），质量分数为 的盐酸，蒸馏水【实验步骤】\n\n①在载玻片上用滴管滴一滴生理盐水，用牙签在口腔一侧轻轻刮几下，再把牙签浸入载玻片的生理盐水中，使细胞留在载玻片上，点燃酒精灯烘干载玻片。\n\n②在小烧杯中加入30ml 质量分数为 的盐酸，再取一个大烧杯，大烧杯内装 温水，然后把小烧杯放入大烧杯内，最后把烘干好的载玻片放入小烧杯内，要使载玻片上的细胞都浸入盐酸溶液中，保温5分钟。\n\n③用蒸馏水的缓水流冲洗载玻片10秒。\n\n④用吸水纸吸去载玻片上的水分，将甲基绿吡罗红混合染色剂滴2滴在载玻片上，染色5分钟。再用吸水纸吸去多余染色剂，盖上盖玻片。\n\n⑤先用低倍镜观察，选择染色均匀、色泽浅的区域，移至视野中央，将物调节清晰，然后用高倍镜观察，调节细准焦螺旋，观察细胞核和细胞质的染色情况。\n\n【实验结果】细胞核区域呈绿色，细胞质区域呈红色。","explanation":"100\n\n本题考查生物实验。\n\nA项错误，步骤②将细胞置于盐酸中5分钟，已经对细胞结构产生了的破坏一一破坏细胞膜，增加细胞膜的通透性，以方便染色剂进入细胞，同时，盐酸还能使细胞中染色体中的 DNA 和蛋白质分离，有利于DNA 与染色剂结合。\n\nB项正确，甲基绿和吡罗红均为碱性染料，步骤③中冲洗载玻片是为了洗去盐酸，避免酸性环境影响染色效果。\n\nC项错误，步骤④用吸水纸吸去载玻片上的水分，说明进行染色时需要使细胞保持干燥，避免水分稀释染色剂。\n\nD项错误，步骤①进行烘烤、步骤②用盐酸进行解离，已对细胞产生不可逆破坏，无法恢复活性。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2022/2022-11-12/策略选择.md","module":"综合分析","sourceModule":"策略选择","sourceType":"实验设计","questionPages":[22],"answerPages":[31]},"idx":99,"pid":"p2065d6d72f","sourceYears":[2022]}]};
